            target = -RISK_PERCENT * current_bar.close / (1 * atr)
            target = max(MIN_TRADE_SIZE, min(MAX_TRADE_SIZE, target))
            stop = current_bar.close + STOP_AHEAD_ATR * atr
            take = None
            state['entry_price'] = current_bar.close
            state['entry_atr'] = entry_atr
            state['trade_bars'] = 0
            return {"target": target, "stop": stop, "take": take}

    # Check for exit conditions
    if pos > 0:
        if current_bar.low <= state['entry_price'] - STOP_AHEAD_ATR * state['entry_atr']:
            return {"target": 0, "stop": None, "take": None}
        if current_bar.high >= state['entry_price'] + entry_atr:
            take = state['entry_price'] + entry_atr
            return {"target": pos, "stop": None, "take": take}
        if state['trade_bars'] >= MAX_TRADE_BARS:
            return {"target": 0, "stop": None, "take": None}
