def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    RISK_PER_ATR = 0.01
    K_ATR = 2
    STOP_ATR = 1
    TAKE_ATR = 2
    ADD_ATR = 2
    MAX_SIZE = 1.0

    # Initialize state if not already set
    if 'entry_price' not in state:
        state['entry_price'] = hist.close[-1]
        state['add_price'] = None
        state['box_size'] = 0.0

    entry_price = state['entry_price']
    add_price = state['add_price']
    box_size = state['box_size']

    # Calculate target position
    if pos == 0:
        macd_line, signal_line, _ = ind.macd(hist.close, 12, 26, 9)
        if macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
            target = RISK_PER_ATR * hist.close[-1] / (K_ATR * ENTRY_ATR)
            target = min(target, MAX_SIZE)
            state['add_price'] = entry_price + ADD_ATR * ENTRY_ATR
            state['box_size'] = target
            return {"target": target, "stop": entry_price - STOP_ATR * ENTRY_ATR, "take": entry_price + TAKE_ATR * ENTRY_ATR}

    # Check for pyramid addition
    if pos > 0 and hist.close[-1] >= add_price:
        add_target = RISK_PER_ATR * hist.close[-1] / (K_ATR * ENTRY_ATR)
        add_target = min(add_target, MAX_SIZE - pos)
        pos += add_target
        add_price = hist.close[-1] + ADD_ATR * ENTRY_ATR
        state['add_price'] = add_price
        state['box_size'] += add_target
        return {"target": pos, "stop": entry_price - STOP_ATR * ENTRY_ATR, "take": entry_price + TAKE_ATR * ENTRY_ATR}

    # Check for box ratcheting
    if pos > 0 and hist.close[-1] >= entry_price + (box_size + ADD_ATR * ENTRY_ATR):
        box_size += ADD_ATR * ENTRY_ATR
        state['box_size'] = box_size
        return {"target": pos, "stop": entry_price - STOP_ATR * ENTRY_ATR, "take": entry_price + TAKE_ATR * ENTRY_ATR}

    # Check for stop and take
    if pos > 0:
        if hist.low[-1] <= entry_price - STOP_ATR * ENTRY_ATR:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.high[-1] >= entry_price + TAKE_ATR * ENTRY_ATR:
            return {"target": 0.0, "stop": None, "take": None}

    return {"target": pos, "stop": entry_price - STOP_ATR * ENTRY_ATR, "take": entry_price + TAKE_ATR * ENTRY_ATR}

