def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 960:
        return {"target": pos, "stop": None, "take": None}

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, 8, 17, 9)

    # Get the current MACD and signal values
    current_macd = macd_line[-1]
    current_signal = signal_line[-1]

    # Get the previous MACD and signal values
    previous_macd = macd_line[-2]
    previous_signal = signal_line[-2]

    # Determine the current trend
    if current_macd > current_signal:
        trend = "long"
    elif current_macd < current_signal:
        trend = "short"
    else:
        trend = "flat"

    # Determine the previous trend
    if previous_macd > previous_signal:
        previous_trend = "long"
    elif previous_macd < previous_signal:
        previous_trend = "short"
    else:
        previous_trend = "flat"

    # Determine the entry price and ATR
    if trend == "long" and previous_trend == "short":
        entry_price = hist.close[-2]
        entry_atr = ind.atr(hist, 14)[-2]
    elif trend == "short" and previous_trend == "long":
        entry_price = hist.close[-2]
        entry_atr = ind.atr(hist, 14)[-2]
    else:
        return {"target": pos, "stop": None, "take": None}

    # Determine the target position
    if trend == "long":
        target = 0.25
    elif trend == "short":
        target = -0.25
    else:
        return {"target": pos, "stop": None, "take": None}

    # Determine the stop price
    stop_price = entry_price - entry_atr

    # Determine the take price
    take_price = entry_price + 2 * entry_atr

    # Check for pyramid
    if "last_add_price" in state and "last_add_time" in state:
        last_add_price = state["last_add_price"]
        last_add_time = state["last_add_time"]
        if trend == "long" and hist.close[-1] >= last_add_price + 2 * entry_atr:
            target += 0.25
        elif trend == "short" and hist.close[-1] <= last_add_price - 2 * entry_atr:
            target -= 0.25

    # Check for MACD cross
    if trend != previous_trend:
        target = 0

    # Check for time limit
    if "start_time" not in state:
        state["start_time"] = hist.time[-1]
    if hist.time[-1] - state["start_time"] >= 128 * 15 * 60 * 1000:
        target = 0

    # Round target to 0.05 grid
    target = round(target, 2)

    # Ensure target is within [-1, 1]
    target = max(-1, min(1, target))

    # Ensure stop and take are within the current price range
    if trend == "long":
        stop_price = max(hist.low[-1], stop_price)
        take_price = min(hist.high[-1], take_price)
    elif trend == "short":
        stop_price = min(hist.high[-1], stop_price)
        take_price = max(hist.low[-1], take_price)

    # Update state
    if target != pos:
        state["last_add_price"] = hist.close[-1]
        state["last_add_time"] = hist.time[-1]

    return {"target": target, "stop": stop_price, "take": take_price}

