def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 960:
        return {"target": pos, "stop": None, "take": None}

    # Calculate EMAs
    ema_5 = ind.ema(hist.close, 5)
    ema_50 = ind.ema(hist.close, 50)
    ema_20_htf = ind.ema(hist.htf(240).close, 20)

    # Calculate ATR
    atr = ind.atr(hist, 14)

    # Determine signal
    if ema_5[-1] > ema_50[-1] and ema_5[-2] <= ema_50[-2] and ema_5[-1] > ema_20_htf[-1]:
        signal = 1  # Long
    elif ema_5[-1] < ema_50[-1] and ema_5[-2] >= ema_50[-2] and ema_5[-1] < ema_20_htf[-1]:
        signal = -1  # Short
    else:
        signal = 0  # No trade

    # Determine target position
    if signal != 0:
        target = signal * 1.0  # Fixed position size of 1
    else:
        target = pos

    # Determine stop and take levels
    if signal == 1:
        stop = hist.low[-1] - 1.5 * atr[-1]
        take = hist.high[-1] + 1.0 * atr[-1]
    elif signal == -1:
        stop = hist.high[-1] + 1.5 * atr[-1]
        take = hist.low[-1] - 1.0 * atr[-1]
    else:
        stop = None
        take = None

    # Check for time stop
    if 'time_stop' not in state:
        state['time_stop'] = len(hist) - 1
    if len(hist) - state['time_stop'] >= 16:
        target = 0

    # Check for opposite signal
    if 'opposite_signal' not in state:
        state['opposite_signal'] = False
    if signal != 0 and pos != 0:
        state['opposite_signal'] = True
    if state['opposite_signal'] and signal == 0:
        target = 0

    return {"target": target, "stop": stop, "take": take}

