    MAX_ADDS = 2
    ADD_SIZE_FACTOR = 0.5
    TAKE_PROFIT_ATR = 3
    TIME_STOP_BARS = 32
    MAX_POSITION = 2

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate entry ATR
    entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    # Calculate box levels
    box_high = ind.highest(hist.close, BOX_PERIOD)[-1]
    box_low = ind.lowest(hist.close, BOX_PERIOD)[-1]

    # Check for breakout conditions
    if pos == 0:
        if current_bar.close > box_high and current_bar.close - box_high <= 4 * entry_atr:
            target = ADD_SIZE_FACTOR
            stop = box_high - 2 * entry_atr
            take = box_high + TAKE_PROFIT_ATR * entry_atr
        elif current_bar.close < box_low and box_low - current_bar.close <= 4 * entry_atr:
            target = -ADD_SIZE_FACTOR
            stop = box_low + 2 * entry_atr
            take = box_low - TAKE_PROFIT_ATR * entry_atr
    else:
        if pos > 0:
            if current_bar.close >= state.get('last_add_price', 0) + 2 * entry_atr:
                if state.get('adds', 0) < MAX_ADDS:
                    target += ADD_SIZE_FACTOR
                    state['adds'] += 1
                    state['last_add_price'] = current_bar.close
        else:
            if current_bar.close <= state.get('last_add_price', 0) - 2 * entry_atr:
                if state.get('adds', 0) < MAX_ADDS:
                    target -= ADD_SIZE_FACTOR
                    state['adds'] += 1
                    state['last_add_price'] = current_bar.close

    # Apply position cap
    if abs(target) > MAX_POSITION:
        target = math.copysign(MAX_POSITION, target)

    # Check for time stop
    if state.get('time_stop', 0) > 0:
        target = 0
        state['time_stop'] -= 1

    # Check for opposite box close
    if pos > 0 and current_bar.close < box_low:
        target = 0
    elif pos < 0 and current_bar.close > box_high:
        target = 0

    # Check for stop and take
    if pos > 0:
        if current_bar.low <= stop:
            target = 0
        if current_bar.high >= take:
            target = 0
    else:
        if current_bar.high >= stop:
            target = 0
        if current_bar.low <= take:
            target = 0

    # Update state
    if target != 0:
        state['time_stop'] = TIME_STOP_BARS

    return {"target": target, "stop": stop, "take": take}

