    ARMed_PERIOD = 32
    STOP_ATR = 1
    TAKE_ATR = 2
    RISK_PERCENT = 0.01
    MAX_POSITION = 1.0
    MIN_POSITION = -1.0

    # Helper functions
    def atr_multiplier(atr):
        return RISK_PERCENT * hist.close[-1] / (atr * BREAKOUT_PERIOD)

    def clamp_position(position):
        return max(MIN_POSITION, min(MAX_POSITION, position))

    # State management
    if 'armed' not in state:
        state['armed'] = False
    if 'breakout_level' not in state:
        state['breakout_level'] = None
    if 'signal_bar' not in state:
        state['signal_bar'] = None

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)[-1]

    # Check for breakout
    if hist.high[-1] > ind.highest(hist.high, BREAKOUT_PERIOD)[-1]:
        state['armed'] = True
        state['breakout_level'] = hist.high[-1]
        state['signal_bar'] = len(hist) - 1
    elif hist.low[-1] < ind.lowest(hist.low, BREAKOUT_PERIOD)[-1]:
        state['armed'] = True
        state['breakout_level'] = hist.low[-1]
        state['signal_bar'] = len(hist) - 1

    # Check for signal
    if state['armed']:
        if pos == 0:
            if state['breakout_level'] is not None:
                if hist.low[-1] <= state['breakout_level']:
                    target = 1.0
                    stop = state['breakout_level'] - STOP_ATR * atr
                    take = state['breakout_level'] + TAKE_ATR * atr
                    return {"target": target, "stop": stop, "take": take}
                elif hist.high[-1] >= state['breakout_level']:
                    target = -1.0
                    stop = state['breakout_level'] + STOP_ATR * atr
                    take = state['breakout_level'] - TAKE_ATR * atr
                    return {"target": target, "stop": stop, "take": take}
        else:
            if len(hist) - state['signal_bar'] >= ARMed_PERIOD:
                state['armed'] = False
                state['breakout_level'] = None
                state['signal_bar'] = None
                return {"target": 0.0, "stop": None, "take": None}

    # Ratchet the box if in profit
    if pos != 0:
        if pos > 0 and hist.close[-1] >= hist.close[state['signal_bar']] + TAKE_ATR * atr:
            take += TAKE_ATR * atr
        elif pos < 0 and hist.close[-1] <= hist.close[state['signal_bar']] - TAKE_ATR * atr:
            take -= TAKE_ATR * atr

    # Return no change if no signal
    return {"target": pos, "stop": None, "take": None}

