    ENTRY_ATR_MULTIPLIER = 1
    ENTRY_ATR_CAP = 0.05
    TAKE_PROFIT_ATR = 3
    TAKE_PROFIT_HALF = 0.5
    TRAILING_STOP_ATR = 1.5
    MINUTE_TO_MS = 60 * 1000
    HOUR_TO_MS = 60 * MINUTE_TO_MS
    DAY_TO_MS = 24 * HOUR_TO_MS

    # Helper functions
    def is_breakout(open_price, high_price, low_price, close_price, atr):
        return close_price > high_price - atr or close_price < low_price + atr

    def is_box_breakout(open_price, high_price, low_price, close_price, atr):
        return is_breakout(open_price, high_price, low_price, close_price, atr) and \
               (close_price > high_price - atr or close_price < low_price + atr)

    def is_ema_cross(open_price, close_price, ema):
        return (open_price <= ema and close_price > ema) or (open_price >= ema and close_price < ema)

    def is_ema_crossed(open_price, close_price, ema):
        return (open_price <= ema and close_price > ema) or (open_price >= ema and close_price < ema)

    def is_ema_crossed_above(open_price, close_price, ema):
        return open_price <= ema and close_price > ema

    def is_ema_crossed_below(open_price, close_price, ema):
        return open_price >= ema and close_price < ema

    def is_ema_crossed_above_or_below(open_price, close_price, ema):
        return is_ema_crossed_above(open_price, close_price, ema) or is_ema_crossed_below(open_price, close_price, ema)

