    TRAILING_STOP_ATR_MULTIPLIER = 3
    RATCHET_ATR_MULTIPLIER = 2
    TIME_STOP_BARS = 32
    SMA_5_PERIOD = 5
    SMA_100_PERIOD = 100
    EQUITY_SIZE = 0.75

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate SMAs
    sma_5 = ind.sma(hist.close, SMA_5_PERIOD)[-1]
    sma_100 = ind.sma(hist.close, SMA_100_PERIOD)[-1]

    # Determine entry signal
    if pos == 0:
        if sma_5 > sma_100 and sma_5 > sma_5[-2]:
            entry_price = current_bar.close
            entry_atr = ind.atr(hist, ATR_PERIOD)[-1]
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['target_price'] = entry_price + ENTRY_ATR_MULTIPLIER * entry_atr
            state['stop_price'] = entry_price - TRAILING_STOP_ATR_MULTIPLIER * entry_atr
            state['ratchet_price'] = entry_price
            state['time_stop'] = False
            return {"target": EQUITY_SIZE * entry_price / (entry_atr * RATCHET_ATR_MULTIPLIER), "stop": state['stop_price'], "take": state['target_price']}
        elif sma_5 < sma_100 and sma_5 < sma_5[-2]:
            entry_price = current_bar.close
            entry_atr = ind.atr(hist, ATR_PERIOD)[-1]
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['target_price'] = entry_price - ENTRY_ATR_MULTIPLIER * entry_atr
            state['stop_price'] = entry_price + TRAILING_STOP_ATR_MULTIPLIER * entry_atr
            state['ratchet_price'] = entry_price
            state['time_stop'] = False
            return {"target": -EQUITY_SIZE * entry_price / (entry_atr * RATCHET_ATR_MULTIPLIER), "stop": state['stop_price'], "take": state['target_price']}

    # Check for exit conditions
    if pos > 0:
        if current_bar.low <= state['stop_price']:
            return {"target": 0, "stop": None, "take": None}
