            state['stop_price'] = state['ratchet_price'] + TRAILING_STOP_ATR_MULTIPLIER * state['entry_atr']
            return {"target": pos - EQUITY_SIZE * state['ratchet_price'] / (state['entry_atr'] * RATCHET_ATR_MULTIPLIER), "stop": state['stop_price'], "take": state['target_price']}
        if current_bar.close >= state['entry_price'] + 3 * state['entry_atr']:
