    # Constants
    ATR_PERIOD = 14
    LONG_SIGNAL = 1
    SHORT_SIGNAL = -1
    MAX_PYRAMID_LEVELS = 2
    MAX_SIZE = 1.0
    FLAT_SIGNAL = 0
    TIMEOUT_BARS = 32
    ENTRY_ATR_KEY = 'entry_atr'
    LAST_SIGNAL_KEY = 'last_signal'
    LAST_ADD_BAR_KEY = 'last_add_bar'

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)[-1]

    # Check for long signal
    if previous_bar.close < ind.sma(hist.close, 5)[-1] and current_bar.close >= ind.sma(hist.close, 5)[-1]:
        if hist.htf(240).close[-1] > ind.ema(hist.htf(240).close, 50)[-1]:
            signal = LONG_SIGNAL
        else:
            signal = FLAT_SIGNAL
    # Check for short signal
    elif previous_bar.close > ind.sma(hist.close, 5)[-1] and current_bar.close <= ind.sma(hist.close, 5)[-1]:
        if hist.htf(240).close[-1] < ind.ema(hist.htf(240).close, 50)[-1]:
            signal = SHORT_SIGNAL
        else:
            signal = FLAT_SIGNAL
    else:
        signal = FLAT_SIGNAL

    # Handle timeout
    if signal == FLAT_SIGNAL and state.get(LAST_SIGNAL_KEY, None) != FLAT_SIGNAL:
        if len(hist) - state[LAST_SIGNAL_KEY] >= TIMEOUT_BARS:
            signal = FLAT_SIGNAL

    # Handle opposite cross
    if signal == LONG_SIGNAL and state.get(LAST_SIGNAL_KEY, None) == SHORT_SIGNAL:
        signal = FLAT_SIGNAL
    elif signal == SHORT_SIGNAL and state.get(LAST_SIGNAL_KEY, None) == LONG_SIGNAL:
        signal = FLAT_SIGNAL

    # Handle pyramid
    if signal == LONG_SIGNAL and pos < MAX_SIZE:
        if current_bar.high >= state.get(LAST_ADD_BAR_KEY, -math.inf) + atr:
            pos += 0.5 * (1 - pos)
            state[LAST_ADD_BAR_KEY] = current_bar.time
    elif signal == SHORT_SIGNAL and pos > -MAX_SIZE:
        if current_bar.low <= state.get(LAST_ADD_BAR_KEY, math.inf) - atr:
            pos -= 0.5 * (pos + 1)
            state[LAST_ADD_BAR_KEY] = current_bar.time

    # Ensure position is within bounds
    pos = max(-MAX_SIZE, min(MAX_SIZE, pos))

    # Set target, stop, and take
    if signal == LONG_SIGNAL:
        target = pos
        stop = current_bar.low - atr
        take = current_bar.high + atr
    elif signal == SHORT_SIGNAL:
        target = pos
        stop = current_bar.high + atr
        take = current_bar.low - atr
    else:
        target = pos
        stop = None
        take = None

    # Update state
    if signal != FLAT_SIGNAL:
        state[LAST_SIGNAL_KEY] = signal
        state[ENTRY_ATR_KEY] = atr
        if signal == LONG_SIGNAL:
            state[LAST_ADD_BAR_KEY] = current_bar.time
        elif signal == SHORT_SIGNAL:
            state[LAST_ADD_BAR_KEY] = current_bar.time

    return {"target": target, "stop": stop, "take": take}

