    PROFIT_ATR = 2
    STOP_ATR = 1.5
    LONG_ENTRY_CONDITION = hist.htf(60).close[-1] > ind.ema(hist.htf(60).close, 20)[-1]
    SHORT_ENTRY_CONDITION = hist.htf(60).close[-1] < ind.ema(hist.htf(60).close, 20)[-1]

    # Initialize state if not already set
    if 'last_macd_cross' not in state:
        state['last_macd_cross'] = None
    if 'last_entry_price' not in state:
        state['last_entry_price'] = None
    if 'last_add_time' not in state:
        state['last_add_time'] = None
    if 'add_count' not in state:
        state['add_count'] = 0

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, MACD_FAST, MACD_SLOW, MACD_SIGNAL)

    # Determine MACD crossover
    current_macd_cross = None
    if macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
        current_macd_cross = 'long'
    elif macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]:
        current_macd_cross = 'short'

    # Entry conditions
    if pos == 0:
        if current_macd_cross == 'long' and LONG_ENTRY_CONDITION:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
            state['last_entry_price'] = entry_price
            state['last_add_time'] = hist.time[-1]
            state['add_count'] = 1
            return {"target": ENTRY_SIZE, "stop": entry_price - STOP_ATR * entry_atr, "take": None}
        elif current_macd_cross == 'short' and SHORT_ENTRY_CONDITION:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
            state['last_entry_price'] = entry_price
            state['last_add_time'] = hist.time[-1]
            state['add_count'] = 1
            return {"target": -ENTRY_SIZE, "stop": entry_price + STOP_ATR * entry_atr, "take": None}

    # Exit conditions
    if pos != 0:
        if current_macd_cross == 'long' and pos < 0:
            return {"target": 0, "stop": None, "take": None}
        elif current_macd_cross == 'short' and pos > 0:
            return {"target": 0, "stop": None, "take": None}

    # Add to position if in favor
    if pos != 0 and current_macd_cross == state['last_macd_cross']:
        if pos > 0 and hist.close[-1] >= state['last_entry_price'] + PROFIT_ATR * ind.atr(hist, ENTRY_ATR_PERIOD)[-1]:
            state['add_count'] += 1
            state['add_count'] = min(state['add_count'], MAX_ADDS)
            return {"target": pos + ENTRY_SIZE * state['add_count'], "stop": None, "take": None}
        elif pos < 0 and hist.close[-1] <= state['last_entry_price'] - PROFIT_ATR * ind.atr(hist, ENTRY_ATR_PERIOD)[-1]:
            state['add_count'] += 1
            state['add_count'] = min(state['add_count'], MAX_ADDS)
            return {"target": pos - ENTRY_SIZE * state['add_count'], "stop": None, "take": None}

    # Cooldown
    if pos != 0 and hist.time[-1] - state['last_add_time'] < COOLDOWN_PERIOD * 60 * 1000:
        return {"target": pos, "stop": None, "take": None}

    # Maintain position
    return {"target": pos, "stop": None, "take": None}

