import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    DONCHIAN_PERIOD = 96
    ENTRY_ATR_MULTIPLIER = 1.0
    RISK_PERCENTAGE = 0.0025
    POSITION_CAP = 1.0
    POSITION_FLOOR = 0.05
    TAKE_PROFIT_ATR = 1.5
    TIME_STOP_BARS = 32
    TREND_FILTER_PERIOD = 50
    TREND_FILTER_HTF_PERIOD = 240

    # Helper functions
    def calculate_atr(hist, period):
        return ind.atr(hist, period)[-1]

    def calculate_donchian_levels(hist, period):
        high = ind.highest(hist.high, period)[-1]
        low = ind.lowest(hist.low, period)[-1]
        return high, low

    def calculate_position_size(entry_price, atr, risk_percentage, cap, floor):
        position_size = (risk_percentage * entry_price) / (atr * ENTRY_ATR_MULTIPLIER)
        return max(min(position_size, cap), floor)

    def is_trend_up(hist, period, htf_period):
        htf_close = hist.htf(htf_period).close[-1]
        htf_ema = ind.ema(hist.htf(htf_period).close, period)[-1]
        return htf_close > htf_ema

    # Get current bar data
    current_close = hist.close[-1]
    current_high = hist.high[-1]
    current_low = hist.low[-1]

    # Calculate ATR and Donchian levels
    atr = calculate_atr(hist, ATR_PERIOD)
    donchian_high, donchian_low = calculate_donchian_levels(hist, DONCHIAN_PERIOD)

    # Determine target position
    if pos == 0:
        if current_close > donchian_high:
            target = calculate_position_size(current_close, atr, RISK_PERCENTAGE, POSITION_CAP, POSITION_FLOOR)
            stop = donchian_high
            take = None
        elif current_close < donchian_low:
            target = -calculate_position_size(current_close, atr, RISK_PERCENTAGE, POSITION_CAP, POSITION_FLOOR)
            stop = donchian_low
            take = None
        else:
            target = 0
            stop = None
            take = None
    else:
        target = pos
        stop = None
        take = None

    # Check for breakout and retest
    if pos != 0:
        if pos > 0:
            if current_close >= donchian_high + TAKE_PROFIT_ATR * atr:
                target = pos / 2
                take = donchian_high + TAKE_PROFIT_ATR * atr
            elif current_close <= donchian_high:
                target = 0
                stop = donchian_high
        else:
            if current_close <= donchian_low - TAKE_PROFIT_ATR * atr:
                target = pos / 2
                take = donchian_low - TAKE_PROFIT_ATR * atr
            elif current_close >= donchian_low:
                target = 0
                stop = donchian_low

    # Check for time stop
    if 'time_stop' not in state:
        state['time_stop'] = 0
    if state['time_stop'] > 0:
        state['time_stop'] -= 1
        if state['time_stop'] == 0:
            target = 0

    # Check for trend filter
    if pos != 0:
        if pos > 0:
            if not is_trend_up(hist, TREND_FILTER_PERIOD, TREND_FILTER_HTF_PERIOD):
                target = 0
                stop = None
        else:
            if is_trend_up(hist, TREND_FILTER_PERIOD, TREND_FILTER_HTF_PERIOD):
                target = 0
                stop = None

    # Round target to 0.05 grid
    target = round(target, 2) if target != 0 else 0

    return {"target": target, "stop": stop, "take": take}

