    TAKE_PROFIT_ATR_MULTIPLIER = 1.0
    STOP_TRAILING_ATR_MULTIPLIER = 4.0
    TIME_STOP_BARS = 16
    MIN_ATR = 0.01

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate RSI
    rsi = ind.rsi(hist.close, 21)[-1]

