    atr = ind.atr(hist, 14)[-1]

    # Initialize state variables
    if 'entry_price' not in state:
        state['entry_price'] = None
    if 'entry_atr' not in state:
        state['entry_atr'] = None
    if 'last_add_price' not in state:
        state['last_add_price'] = None
    if 'stop_price' not in state:
        state['stop_price'] = None
    if 'time_stop' not in state:
        state['time_stop'] = False

    # Entry condition
    if pos == 0 and rsi <= RSI_OVERSOLD and previous_bar.low <= current_bar.low:
        state['entry_price'] = current_bar.close
        state['entry_atr'] = atr
        state['last_add_price'] = current_bar.close
        state['stop_price'] = current_bar.high
        state['time_stop'] = False
        return {"target": ENTRY_ATR_MULTIPLIER * state['entry_price'] / state['entry_atr'], "stop": None, "take": None}

    # Pyramid condition
    if pos > 0 and current_bar.high >= state['last_add_price'] + TAKE_PROFIT_ATR_MULTIPLIER * state['entry_atr']:
        state['last_add_price'] = current_bar.close
        return {"target": pos + ENTRY_ATR_MULTIPLIER * state['entry_price'] / state['entry_atr'], "stop": None, "take": None}

    # Take profit condition
    if pos > 0 and current_bar.close >= state['entry_price'] + 0.5 * TAKE_PROFIT_ATR_MULTIPLIER * state['entry_atr']:
        state['stop_price'] = None
        return {"target": 0, "stop": None, "take": None}

    # Trailing stop condition
    if pos > 0 and current_bar.high > state['stop_price']:
        state['stop_price'] = current_bar.high - STOP_TRAILING_ATR_MULTIPLIER * state['entry_atr']

    # Time stop condition
    if pos > 0 and len(hist) - 1 >= TIME_STOP_BARS:
        state['time_stop'] = True

    # Exit condition
    if pos > 0 and (rsi >= RSI_OVERBOUGHT or state['time_stop']):
        return {"target": 0, "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": state['stop_price'], "take": None}

