def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RSI_PERIOD = 14
    RSI_LONG_ENTRY = 30
    RSI_SHORT_ENTRY = 70
    RSI_CROSSOVER = 14
    ENTRY_ATR_PERIOD = 14
    STOP_FACTOR = 2
    TAKE_FACTOR = 2
    PYRAMID_ADD = 0.5
    PYRAMID_MAX = 1.5
    VOLATILITY_RISK = 0.01
    VOLATILITY_K = 1
    VOLATILITY_CAP = 0.05
    VOLATILITY_FLOOR = 0.01
    FILTER_PERIOD = 20
    FILTER_EMA_PERIOD = 20

    # Get current bar and previous bar
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate RSI and its signal
    rsi = ind.rsi(hist.close, RSI_PERIOD)
    rsi_signal = ind.rsi(hist.close, RSI_CROSSOVER)

    # Calculate entry ATR
    entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    # Calculate filter
    filter_ema = ind.ema(hist.htf(60).close, FILTER_EMA_PERIOD)[-1]

    # Determine entry conditions
    if pos == 0:
        if rsi_signal[-1] < RSI_LONG_ENTRY and current_bar.close > filter_ema:
            target = VOLATILITY_RISK * current_bar.close / (VOLATILITY_K * entry_atr)
            target = max(VOLATILITY_FLOOR, min(VOLATILITY_CAP, target))
            stop = current_bar.close - STOP_FACTOR * entry_atr
            take = current_bar.close + TAKE_FACTOR * entry_atr
            return {"target": target, "stop": stop, "take": take}
        elif rsi_signal[-1] > RSI_SHORT_ENTRY and current_bar.close < filter_ema:
            target = -VOLATILITY_RISK * current_bar.close / (VOLATILITY_K * entry_atr)
            target = max(VOLATILITY_FLOOR, min(VOLATILITY_CAP, target))
            stop = current_bar.close + STOP_FACTOR * entry_atr
            take = current_bar.close - TAKE_FACTOR * entry_atr
            return {"target": target, "stop": stop, "take": take}

    # Determine exit conditions
    if pos > 0:
        if rsi[-1] > RSI_LONG_ENTRY or current_bar.low <= state.get("stop", float('inf')):
            return {"target": 0}
        elif current_bar.high >= state.get("take", float('-inf')):
            return {"target": 0}
    elif pos < 0:
        if rsi[-1] < RSI_SHORT_ENTRY or current_bar.high >= state.get("stop", float('-inf')):
            return {"target": 0}
        elif current_bar.low <= state.get("take", float('inf')):
            return {"target": 0}

    # Pyramid logic
    if pos > 0 and current_bar.high >= state.get("take", float('-inf')):
        if pos + PYRAMID_ADD <= PYRAMID_MAX:
            return {"target": pos + PYRAMID_ADD}
    elif pos < 0 and current_bar.low <= state.get("take", float('inf')):
        if pos - PYRAMID_ADD >= -PYRAMID_MAX:
            return {"target": pos - PYRAMID_ADD}

    return {"target": pos}

