            state['stop_loss'] = None
            state['take_profit'] = None
            state['ratchet_count'] = 0
            state['time_stop_counter'] = 0
        else:
            state['time_stop_counter'] += 1
            if state['time_stop_counter'] >= TIME_STOP:
