    RISK_PER_ATR = 0.01
    K_ATR = 4
    MAX_ADDS = 2
    TIME_STOP_BARS = 128
    ENTRY_ATR_PERIOD = 14
    EMA_PERIOD = 10
    SIGNAL_PERIOD = 100

    # Get current bar index
    t = len(hist) - 1

    # Calculate entry ATR
    entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    # Calculate EMAs
    ema_fast = ind.ema(hist.close, EMA_PERIOD)[-1]
    ema_slow = ind.ema(hist.close, SIGNAL_PERIOD)[-1]

    # Determine target position
    if pos == 0:
        if ema_fast > ema_slow:
            target = RISK_PER_ATR * hist.close[-1] / (K_ATR * entry_atr)
        elif ema_fast < ema_slow:
            target = -RISK_PER_ATR * hist.close[-1] / (K_ATR * entry_atr)
        else:
            target = pos
    else:
        target = pos

    # Calculate stop and take levels
    if pos > 0:
        stop = hist.low[-1] - entry_atr
        take = hist.high[-1] + entry_atr
    elif pos < 0:
        stop = hist.high[-1] + entry_atr
        take = hist.low[-1] - entry_atr
    else:
        stop = None
        take = None

    # Check for time stop
    if 'time_stop' in state and state['time_stop'] + TIME_STOP_BARS <= t:
        target = 0

    # Check for pyramid adds
    if 'add_count' in state and state['add_count'] < MAX_ADDS:
        if pos > 0 and hist.close[-1] >= hist.close[-2] + entry_atr:
            target += RISK_PER_ATR * hist.close[-1] / (K_ATR * entry_atr)
        elif pos < 0 and hist.close[-1] <= hist.close[-2] - entry_atr:
            target -= RISK_PER_ATR * hist.close[-1] / (K_ATR * entry_atr)

    # Round target to 0.05 grid
    target = round(target, 2) / 0.05 * 0.05

    # Update state
    if target != pos:
        if 'time_stop' in state:
            del state['time_stop']
        if 'add_count' in state:
            del state['add_count']
    elif 'time_stop' not in state and 'add_count' not in state:
        state['time_stop'] = t
        state['add_count'] = 0

    return {"target": target, "stop": stop, "take": take}

