def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RISK_PERCENT = 0.0025
    K_ATR = 2
    STOP_ATR = 1
    TAKE_ATR = 3
    RATCHET_ATR = 2
    TIME_STOP_BARS = 128

    # Helper functions
    def atr_multiplier():
        return RISK_PERCENT * hist.close[-1] / (K_ATR * ind.atr(hist, 14)[-1])

    def ratchet_stop(current_stop, current_price, entry_price, atr):
        if current_price >= entry_price + RATCHET_ATR * atr:
            return entry_price + RATCHET_ATR * atr
        return current_stop

    def trail_stop(current_stop, current_price, extreme_price, atr):
        if current_price <= extreme_price - 2 * atr:
            return extreme_price - 2 * atr
        return current_stop

    # State management
    if 'entry_price' not in state:
        state['entry_price'] = None
        state['entry_atr'] = None
        state['stop_price'] = None
        state['take_price'] = None
        state['time_stop'] = None

    # Trend filter
    if len(hist) < 60:  # 1h candle required for trend filter
        return {"target": pos, "stop": None, "take": None}

    htf_1h = hist.htf(60)
    ema_20 = ind.ema(hist.close, 20)[-1]
    ema_50 = ind.ema(hist.close, 50)[-1]
    htf_1h_ema_20 = ind.ema(htf_1h.close, 20)[-1]

    if pos == 0:
        if ema_20 > ema_50 and htf_1h_ema_20 > htf_1h.close[-1]:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ind.atr(hist, 14)[-1]
            state['stop_price'] = state['entry_price'] - STOP_ATR * state['entry_atr']
            state['take_price'] = state['entry_price'] + TAKE_ATR * state['entry_atr']
            state['time_stop'] = len(hist) + TIME_STOP_BARS
            return {"target": atr_multiplier(), "stop": state['stop_price'], "take": state['take_price']}
        elif ema_20 < ema_50 and htf_1h_ema_20 < htf_1h.close[-1]:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ind.atr(hist, 14)[-1]
            state['stop_price'] = state['entry_price'] + STOP_ATR * state['entry_atr']
            state['take_price'] = state['entry_price'] - TAKE_ATR * state['entry_atr']
            state['time_stop'] = len(hist) + TIME_STOP_BARS
            return {"target": -atr_multiplier(), "stop": state['stop_price'], "take": state['take_price']}
    else:
        if len(hist) >= state['time_stop']:
            return {"target": 0, "stop": None, "take": None}

        current_price = hist.close[-1]
        current_stop = state['stop_price']
        current_take = state['take_price']
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']

        if pos > 0:
            current_stop = ratchet_stop(current_stop, current_price, entry_price, entry_atr)
            current_stop = trail_stop(current_stop, current_price, hist.low[-1], entry_atr)
            if current_price >= current_take:
                return {"target": 0, "stop": None, "take": None}
        else:
            current_stop = ratchet_stop(current_stop, current_price, entry_price, entry_atr)
            current_stop = trail_stop(current_stop, current_price, hist.high[-1], entry_atr)
            if current_price <= current_take:
                return {"target": 0, "stop": None, "take": None}

        return {"target": pos, "stop": current_stop, "take": current_take}

