def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 961:
        return {"target": pos, "stop": None, "take": None}

    # Calculate EMAs
    ema_5 = ind.ema(hist.close, 5)
    ema_100 = ind.ema(hist.close, 100)
    ema_20 = ind.ema(hist.htf(60).close, 20)

    # Check for long entry condition
    if ema_5[-1] > ema_100[-1] and ema_5[-2] <= ema_100[-2] and hist.htf(60).close[-1] > ema_20[-1]:
        if 'entry_price' not in state:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ind.atr(hist, 14)[-1]
            state['stop'] = state['entry_price'] - 2 * state['entry_atr']
            state['take'] = state['entry_price'] + 3 * state['entry_atr']
            state['box_high'] = state['entry_price'] + 3 * state['entry_atr']
            state['box_low'] = state['entry_price'] - 2 * state['entry_atr']
            state['target'] = min(1.0, 0.005 * state['entry_price'] / (3 * state['entry_atr']))
        else:
            state['target'] = min(1.0, 0.005 * state['entry_price'] / (3 * state['entry_atr']))
            state['stop'] = state['box_low']
            state['take'] = state['box_high']
    else:
        state['target'] = 0.0
        state['stop'] = None
        state['take'] = None

    # Check for long exit conditions
    if pos > 0:
        if hist.low[-1] <= state['stop']:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.high[-1] >= state['take']:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.close[-1] >= state['entry_price'] + state['entry_atr']:
            state['box_high'] += state['entry_atr']
            state['box_low'] += state['entry_atr']
            state['stop'] = state['box_low']
            state['take'] = state['box_high']

    return {"target": state['target'], "stop": state['stop'], "take": state['take']}

