def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 961:
        return {"target": pos, "stop": None, "take": None}

    current_bar = len(hist) - 1
    high_96 = ind.highest(hist.high, 96)
    low_96 = ind.lowest(hist.low, 96)
    atr_14 = ind.atr(hist, 14)
    close = hist.close[-1]

    if 'armed' not in state:
        state['armed'] = False
        state['anchor'] = None
        state['target'] = None
        state['stop'] = None
        state['add_count'] = 0

    if not state['armed'] and close > high_96[-1]:
        state['armed'] = True
        state['anchor'] = close
        state['target'] = close + 3 * atr_14[-1]
        state['stop'] = close - atr_14[-1]
        state['add_count'] = 0

    if state['armed']:
        if close < state['stop']:
            return {"target": 0, "stop": None, "take": None}
        if close >= state['target']:
            return {"target": pos, "stop": None, "take": None}
        if close >= state['anchor'] + 2 * atr_14[-1]:
            state['anchor'] += 2 * atr_14[-1]
            state['target'] += 2 * atr_14[-1]
            state['add_count'] += 1
            if state['add_count'] < 2:
                return {"target": pos + 0.25, "stop": state['stop'], "take": state['target']}

    return {"target": pos, "stop": state['stop'], "take": state['target']}

