    if pos == 0:
        if hist.close[-1] > box_high:
            return {"target": 1.0, "stop": box_high - 2 * atr, "take": box_high + 2 * atr}
        elif hist.close[-1] < box_low:
            return {"target": -1.0, "stop": box_low + 2 * atr, "take": box_low - 2 * atr}

    # Check for timeout or opposite signal
    if 'signal_time' in state and hist.time[-1] - state['signal_time'] > 64 * 15 * 60 * 1000:
        return {"target": 0, "stop": None, "take": None}

    if 'opposite_signal' in state and state['opposite_signal']:
        return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

