    ENTRY_ATR = ind.atr(hist, 14)[-1]
    STOP_ATR = 1
    TAKE_ATR = 2
    TRAIL_ATR = 3
    MAX_PYRAMID = 2
    ADD_SIZE = 0.25
    TIME_STOP = 128

    # State management
    if 'entry_price' not in state:
        state['entry_price'] = None
    if 'entry_atr' not in state:
        state['entry_atr'] = None
    if 'stop_price' not in state:
        state['stop_price'] = None
    if 'take_price' not in state:
        state['take_price'] = None
    if 'trail_price' not in state:
        state['trail_price'] = None
    if 'last_add_price' not in state:
        state['last_add_price'] = None
    if 'last_add_bar' not in state:
        state['last_add_bar'] = None
    if 'time_stop_bar' not in state:
        state['time_stop_bar'] = None

    # Calculate position size
    if pos == 0:
        if hist.close[-1] > ind.sma(hist.close, 20)[-1] and hist.close[-1] > ind.sma(hist.close, 200)[-1]:
            target = RISK_PER_ATR * hist.close[-1] / (K_ATR * ENTRY_ATR)
            target = round(target / 0.05) * 0.05
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ENTRY_ATR
            state['stop_price'] = hist.close[-1] - STOP_ATR * ENTRY_ATR
            state['take_price'] = hist.close[-1] + TAKE_ATR * ENTRY_ATR
            state['trail_price'] = hist.close[-1] - TRAIL_ATR * ENTRY_ATR
            state['last_add_price'] = hist.close[-1]
            state['last_add_bar'] = len(hist) - 1
            state['time_stop_bar'] = len(hist) - 1 + TIME_STOP
