import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 961:
        return {"target": pos, "stop": None, "take": None}

    close = hist.close
    sma_5 = ind.sma(close, 5)
    sma_200 = ind.sma(close, 200)

    if sma_5[-1] > sma_200[-1] and sma_5[-2] <= sma_200[-2]:
        if pos == 0:
            atr = ind.atr(hist, 14)[-1]
            target = 0.25 * close[-1] / (1 * atr)
            stop = close[-1] - atr
            take = close[-1] + 3 * atr
            state['entry_price'] = close[-1]
            state['entry_atr'] = atr
            return {"target": target, "stop": stop, "take": take}
        else:
            return {"target": pos, "stop": None, "take": None}
    elif sma_5[-1] < sma_200[-1] and sma_5[-2] >= sma_200[-2]:
        if pos == 0:
            return {"target": pos, "stop": None, "take": None}
        else:
            return {"target": 0, "stop": None, "take": None}
    else:
        if pos != 0:
            entry_price = state.get('entry_price', None)
            entry_atr = state.get('entry_atr', None)
            if entry_price is not None and entry_atr is not None:
                if close[-1] >= entry_price + entry_atr:
                    return {"target": 0, "stop": None, "take": None}
                else:
                    return {"target": pos, "stop": entry_price, "take": None}
        return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 960:
        return {"target": pos, "stop": None, "take": None}

    close = hist.close
    sma5 = ind.sma(close, 5)
    sma100 = ind.sma(close, 100)
    atr = ind.atr(hist, 14)

    if pos == 0:
        if sma5[-1] > sma100[-1] and sma5[-2] <= sma100[-2]:
            entry_price = close[-1]
            entry_atr = atr[-1]
            target = 0.25 * close[-1] / (1 * entry_atr)
            stop = entry_price - 2 * entry_atr
            take = entry_price + 2 * entry_atr
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['target'] = target
            state['stop'] = stop
            state['take'] = take
            state['add_price'] = entry_price
            state['add_count'] = 0
            return {"target": target, "stop": stop, "take": take}
    else:
        if sma5[-1] < sma100[-1] and sma5[-2] >= sma100[-2]:
            return {"target": 0, "stop": None, "take": None}

        if close[-1] >= state['add_price'] + 2 * state['entry_atr']:
            state['add_price'] = close[-1]
            state['add_count'] += 0.25
            if state['add_count'] > 1:
                state['add_count'] = 1
            target = state['add_count'] * close[-1] / (1 * state['entry_atr'])
            return {"target": target, "stop": state['stop'], "take": state['take']}

    return {"target": pos, "stop": state['stop'], "take": state['take']}

