import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 960:
        return {"target": pos, "stop": None, "take": None}

    ema_100 = ind.ema(hist.close, 100)
    ema_20 = ind.ema(hist.close, 20)

    if ema_20[-1] > ema_100[-1] and ema_20[-2] <= ema_100[-2]:
        if pos == 0:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            target = min(1.0, max(0.05, 0.0025 * entry_price / entry_atr))
            stop = entry_price - 3 * entry_atr
            take = entry_price + 3 * entry_atr
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['signal_time'] = hist.time[-1]
            state['bar_count'] = 0
            return {"target": target, "stop": stop, "take": take}
        elif pos < 0:
            state['signal_time'] = hist.time[-1]
            state['bar_count'] = 0
            return {"target": 0, "stop": None, "take": None}

    if ema_20[-1] < ema_100[-1] and ema_20[-2] >= ema_100[-2]:
        if pos == 0:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            target = max(-1.0, min(-0.05, -0.0025 * entry_price / entry_atr))
            stop = entry_price + 3 * entry_atr
            take = entry_price - 3 * entry_atr
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['signal_time'] = hist.time[-1]
            state['bar_count'] = 0
            return {"target": target, "stop": stop, "take": take}
        elif pos > 0:
            state['signal_time'] = hist.time[-1]
            state['bar_count'] = 0
            return {"target": 0, "stop": None, "take": None}

    if 'entry_price' in state and 'entry_atr' in state:
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        bar_count = state.get('bar_count', 0) + 1
        state['bar_count'] = bar_count

        if bar_count >= 64:
            return {"target": 0, "stop": None, "take": None}

        if pos > 0 and hist.close[-1] >= entry_price + 3 * entry_atr:
            target = max(0.0, pos / 2)
            return {"target": target, "stop": None, "take": None}

        if pos < 0 and hist.close[-1] <= entry_price - 3 * entry_atr:
            target = min(0.0, pos / 2)
            return {"target": target, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

