def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = 4
    BREAKOUT_ATR = 1
    PROFIT_ATR = 0.5
    HARD_STOP_ATR = 3
    RISK_PERCENT = 0.05
    K_ATR = 1
    MAX_SIZE = 1.0
    ENTRY_EMA_PERIOD = 50
    BREAKOUT_PERIOD = 64
    HIGHER_TIMEFRAME = 60

    # Helper functions
    def is_flat():
        return pos == 0

    def is_long():
        return pos > 0

    def is_short():
        return pos < 0

    def calculate_position_size(entry_price, atr):
        return RISK_PERCENT * entry_price / (K_ATR * atr)

    def calculate_entry_price():
        return hist.close[-1]

    def calculate_atr():
        return ind.atr(hist, BREAKOUT_PERIOD)[-1]

    def calculate_ema():
        return ind.ema(hist.close, ENTRY_EMA_PERIOD)[-1]

    def is_breakout():
        high = ind.highest(hist.high, BREAKOUT_PERIOD)[-1]
        return hist.close[-1] > high

    def is_ema_cross():
        ema = ind.ema(hist.close, ENTRY_EMA_PERIOD)[-1]
        ema_prev = ind.ema(hist.close, ENTRY_EMA_PERIOD)[-2]
        return ema > ema_prev and ema_prev <= hist.close[-2] and ema > hist.close[-1]

    def is_profit():
        return hist.close[-1] >= state.get('entry_price', 0) + PROFIT_ATR * state.get('entry_atr', 0)

    def is_hard_stop():
        return hist.close[-1] <= state.get('entry_price', 0) - HARD_STOP_ATR * state.get('entry_atr', 0)

    def is_take_profit():
        return hist.close[-1] >= state.get('entry_price', 0) + HARD_STOP_ATR * state.get('entry_atr', 0)

    # Main logic
    if is_flat():
        if is_breakout() and is_ema_cross():
            entry_price = calculate_entry_price()
            entry_atr = calculate_atr()
            position_size = calculate_position_size(entry_price, entry_atr)
            position_size = min(position_size, MAX_SIZE)
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['position_size'] = position_size
            return {"target": position_size, "stop": entry_price - HARD_STOP_ATR * entry_atr, "take": entry_price + HARD_STOP_ATR * entry_atr}
        else:
            return {"target": pos, "stop": None, "take": None}
    else:
        if is_profit():
            state['position_size'] = 0
            return {"target": 0, "stop": None, "take": None}
        elif is_hard_stop():
            state['position_size'] = 0
            return {"target": 0, "stop": None, "take": None}
        elif is_take_profit():
            state['position_size'] = 0
            return {"target": 0, "stop": None, "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}

