    box_low = ind.lowest(hist.close, BOX_PERIOD)[-1]

    # Calculate HTF EMA
    htf_ema = ind.ema(hist.htf(HTF_PERIOD).close, HTF_EMA_PERIOD)[-1]

    # Determine if we are in a long or short position
    if pos > 0:
        position_type = 'long'
    elif pos < 0:
        position_type = 'short'
    else:
        position_type = 'flat'

    # Determine if we are in a trend
    if position_type == 'long':
        in_trend = current_bar.close > htf_ema
    elif position_type == 'short':
        in_trend = current_bar.close < htf_ema
    else:
        in_trend = True

    # Determine if we are in a breakout
    if position_type == 'long':
        in_breakout = current_bar.close > box_high
    elif position_type == 'short':
        in_breakout = current_bar.close < box_low
    else:
