    # Determine if we are in a time stop
    if position_type != 'flat':
        in_time_stop = state.get('time_stop', 0) > 0
    else:
        in_time_stop = False

    # Determine if we are in a hard stop
    if position_type != 'flat':
        hard_stop_price = current_bar.close - pos * entry_atr * HARD_STOP_ATR
        in_hard_stop = current_bar.low <= hard_stop_price
    else:
        in_hard_stop = False

    # Determine if we are in a take profit
    if position_type != 'flat':
        take_profit_price = current_bar.close + pos * entry_atr * RISK_PER_ATR * K_ATR
        in_take_profit = current_bar.high >= take_profit_price
    else:
        in_take_profit = False

    # Determine if we are in a stop loss
    if position_type != 'flat':
        stop_loss_price = current_bar.close - pos * entry_atr * RISK_PER_ATR * K_ATR
        in_stop_loss = current_bar.low <= stop_loss_price
    else:
        in_stop_loss = False

    # Determine if we are in a new signal
    if position_type == 'flat' and in_trend and in_breakout:
        if position_type == 'long':
            target = 1.0
        elif position_type == 'short':
            target = -1.0
        else:
            target = 0.0
    else:
        target = pos

