    if in_hard_stop or in_stop_loss:
        target = 0.0

    # Determine if we are in a new take profit
    if in_take_profit:
        target = 0.0

    # Determine if we are in a new time stop
    if in_time_stop:
        target = 0.0

    # Determine if we are in a new position
    if target != pos:
        state['time_stop'] = 0
    else:
        state['time_stop'] += 1

