import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RISK_PERCENT = 0.0025
    K_ATR = 2
    MAX_ENTRIES_PER_DAY = 3
    PROFIT_ATR = 2
    TRAILING_STOP_ATR = 3
    MACD_FAST = 12
    MACD_SLOW = 26
    MACD_SIGNAL = 9

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, MACD_FAST, MACD_SLOW, MACD_SIGNAL)

    # Calculate ATR
    atr = ind.atr(hist, 14)

    # Calculate risk and position size
    risk = RISK_PERCENT * hist.close[-1] / (K_ATR * atr[-1])
    position_size = max(min(risk, 1.0), 0.05)

    # Check for new entry conditions
    if pos == 0 and len(state) < MAX_ENTRIES_PER_DAY:
        if macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
            state['entry_price'] = current_bar.close
            state['entry_atr'] = atr[-1]
            state['high_watermark'] = current_bar.high
            state['trailing_stop'] = current_bar.high - TRAILING_STOP_ATR * atr[-1]
            return {"target": position_size, "stop": None, "take": None}

    # Check for take profit and trailing stop
    if pos > 0:
        if current_bar.close >= state['entry_price'] + PROFIT_ATR * state['entry_atr']:
            return {"target": 0, "stop": None, "take": None}
        if current_bar.high > state['high_watermark']:
            state['high_watermark'] = current_bar.high
            state['trailing_stop'] = state['high_watermark'] - TRAILING_STOP_ATR * state['entry_atr']
        if current_bar.low <= state['trailing_stop']:
            return {"target": 0, "stop": None, "take": None}

    # Check for MACD crossover to close position
    if pos > 0 and macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]:
        return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

