    def calculate_position_size(entry_price, atr):
        position_size = RISK_PERCENTAGE * entry_price / (ENTRY_ATR_MULTIPLIER * atr)
        return max(POSITION_FRACTION_FLOOR, min(position_size, POSITION_FRACTION_CAP))

    # State management
    if 'cooldown' not in state:
        state['cooldown'] = 0
    if 'entry_price' not in state:
        state['entry_price'] = None
    if 'entry_atr' not in state:
        state['entry_atr'] = None
    if 'position_size' not in state:
        state['position_size'] = 0

    # Cooldown
    if state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Calculate ATR and box
    atr = ind.atr(hist, 14)[-1]
    high_16 = ind.highest(hist.high, 16)[-1]
    low_16 = ind.lowest(hist.low, 16)[-1]
    box_height = high_16 - low_16

