    RETEST_PERIOD = 16
    TRAILING_ATR_STEPS = 2
    RISK_PERCENT = 0.5
    TIMEOUT_PERIOD = 128
    COOLDOWN_PERIOD = 48

    # Helper functions
    def get_entry_atr():
        return ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    def get_breakout_high():
        return ind.highest(hist.high, BREAKOUT_PERIOD)[-1]

    def get_retest_level():
        return get_breakout_high()

    def get_risk_per_atr():
        return RISK_PERCENT * hist.close[-1] / (TRAILING_ATR_STEPS * get_entry_atr())

    def get_target_price():
        return get_retest_level() + 2 * get_entry_atr()

    def get_stop_price():
        return get_retest_level() - 2 * get_entry_atr()

    # State management
    if 'last_entry_bar' not in state:
        state['last_entry_bar'] = -1
    if 'last_close_price' not in state:
        state['last_close_price'] = hist.close[-1]
    if 'last_target_price' not in state:
        state['last_target_price'] = get_target_price()
    if 'last_stop_price' not in state:
        state['last_stop_price'] = get_stop_price()
    if 'timeout_counter' not in state:
        state['timeout_counter'] = 0
    if 'cooldown_counter' not in state:
        state['cooldown_counter'] = 0

    # Check for breakout
    if pos == 0 and hist.close[-1] > get_breakout_high():
        state['last_entry_bar'] = len(hist) - 1
        state['last_close_price'] = hist.close[-1]
        state['last_target_price'] = get_target_price()
        state['last_stop_price'] = get_stop_price()
        state['timeout_counter'] = 0
        state['cooldown_counter'] = 0
        return {"target": 0.5, "stop": state['last_stop_price'], "take": state['last_target_price']}

    # Check for retest
    if pos != 0 and hist.low[-1] <= get_retest_level():
        state['last_entry_bar'] = len(hist) - 1
        state['last_close_price'] = hist.close[-1]
        state['last_target_price'] = get_target_price()
        state['last_stop_price'] = get_stop_price()
        state['timeout_counter'] = 0
        state['cooldown_counter'] = 0
        return {"target": pos, "stop": state['last_stop_price'], "take": state['last_target_price']}

    # Check for timeout
    if pos != 0 and len(hist) - state['last_entry_bar'] >= TIMEOUT_PERIOD:
        state['last_entry_bar'] = -1
        state['last_close_price'] = hist.close[-1]
        state['last_target_price'] = get_target_price()
        state['last_stop_price'] = get_stop_price()
        state['timeout_counter'] = 0
        state['cooldown_counter'] = 0
        return {"target": 0, "stop": None, "take": None}

    # Check for cooldown
    if pos == 0 and state['cooldown_counter'] > 0:
        state['cooldown_counter'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for trailing stop
    if pos != 0:
        if pos > 0 and hist.low[-1] <= state['last_stop_price']:
            state['last_stop_price'] = hist.low[-1]
        elif pos < 0 and hist.high[-1] >= state['last_stop_price']:
            state['last_stop_price'] = hist.high[-1]

    # Check for take profit
    if pos != 0:
        if pos > 0 and hist.high[-1] >= state['last_target_price']:
            state['last_entry_bar'] = -1
            state['last_close_price'] = hist.close[-1]
            state['last_target_price'] = get_target_price()
            state['last_stop_price'] = get_stop_price()
            state['timeout_counter'] = 0
