        if current_rsi < 25:
            target = ADD_SIZE
        elif current_rsi > 75:
            target = -ADD_SIZE
        else:
            target = pos
    else:
        target = pos

    # Determine stop and take profit levels
    if pos > 0:
        stop = hist.low[-1] - STOP_ATR_MULTIPLIER * entry_atr
        take = hist.high[-1] + TAKE_PROFIT_ATR_MULTIPLIER * entry_atr
    else:
        stop = hist.high[-1] + STOP_ATR_MULTIPLIER * entry_atr
        take = hist.low[-1] - TAKE_PROFIT_ATR_MULTIPLIER * entry_atr

