    if pos != 0:
        if pos > 0:
            if hist.high[-1] >= take:
                target = 0
            elif hist.low[-1] <= stop:
                target = 0
        else:
            if hist.low[-1] <= take:
                target = 0
            elif hist.high[-1] >= stop:
                target = 0

        if target != pos:
            state['last_add_price'] = hist.close[-1]
            state['last_add_atr'] = entry_atr
            if 'adds' not in state:
                state['adds'] = []
            state['adds'].append(hist.close[-1])

    return {"target": target, "stop": stop, "take": take}

