import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RISK_PERCENT = 0.0025
    K_ATR = 2
    COOLDOWN_BARS = 4
    LONG_SIGNAL = 1
    SHORT_SIGNAL = -1
    NO_SIGNAL = 0

    # Helper functions
    def atr_multiplier():
        return RISK_PERCENT * hist.close[-1] / (K_ATR * ind.atr(hist, 14)[-1])

    def cap_position(position):
        return max(0.05, min(1.0, position))

    # State management
    if 'last_signal' not in state:
        state['last_signal'] = NO_SIGNAL
    if 'last_close' not in state:
        state['last_close'] = hist.close[-1]
    if 'last_stop' not in state:
        state['last_stop'] = None
    if 'cooldown' not in state:
        state['cooldown'] = 0

    # Trend filter
    htf_ema = ind.ema(hist.htf(60).close, 20)[-1]
    current_trend = LONG_SIGNAL if hist.close[-1] > htf_ema else SHORT_SIGNAL

    # Signal generation
    if current_trend != state['last_signal']:
        if current_trend == LONG_SIGNAL and hist.close[-1] > ind.highest(hist.close, 20)[-1]:
            state['last_signal'] = LONG_SIGNAL
            state['last_close'] = hist.close[-1]
            state['last_stop'] = None
            state['cooldown'] = COOLDOWN_BARS
        elif current_trend == SHORT_SIGNAL and hist.close[-1] < ind.lowest(hist.close, 20)[-1]:
            state['last_signal'] = SHORT_SIGNAL
            state['last_close'] = hist.close[-1]
            state['last_stop'] = None
            state['cooldown'] = COOLDOWN_BARS

    # Cooldown
    if state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": state['last_stop'], "take": None}

    # Position sizing
    if state['last_signal'] == LONG_SIGNAL:
        target_position = cap_position(atr_multiplier())
    elif state['last_signal'] == SHORT_SIGNAL:
        target_position = -cap_position(atr_multiplier())
    else:
        target_position = pos

