def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    BOX_PERIOD = 32
    MAX_ATR = 6
    RISK_PERCENT = 0.0025
    K_ATR = 2
    STOP_ATR = 2
    TARGET_ATR = 3
    COOLDOWN_PERIOD = 96

    # Helper functions
    def atr_level(atr):
        return hist.close[-1] + atr

    def box_level():
        high = ind.highest(hist.high, BOX_PERIOD)[-1]
        low = ind.lowest(hist.low, BOX_PERIOD)[-1]
        return high, low

    def box_height():
        high, low = box_level()
        return high - low

    def atr_value():
        return ind.atr(hist, ATR_PERIOD)[-1]

    def risk_per_atr():
        return RISK_PERCENT * hist.close[-1] / (K_ATR * atr_value())

    def position_size():
        return max(0.05, min(1, risk_per_atr()))

    def should_enter_long():
        high, low = box_level()
        return hist.close[-1] > high and box_height() <= MAX_ATR * atr_value()

    def should_enter_short():
        high, low = box_level()
        return hist.close[-1] < low and box_height() <= MAX_ATR * atr_value()

    def should_close():
        return hist.close[-1] <= atr_level(-STOP_ATR * atr_value()) or hist.close[-1] >= atr_level(TARGET_ATR * atr_value())

    def should_ratchet():
        return hist.close[-1] >= atr_level(TARGET_ATR * atr_value())

    def should_flip():
        return hist.close[-1] <= atr_level(-STOP_ATR * atr_value())

    # State management
    if 'cooldown' not in state:
        state['cooldown'] = 0

    if 'box_high' not in state:
        state['box_high'] = hist.high[-1]

    if 'box_low' not in state:
        state['box_low'] = hist.low[-1]

    if 'stop_price' not in state:
        state['stop_price'] = None

    if 'target_price' not in state:
        state['target_price'] = None

    if 'position' not in state:
        state['position'] = 0

    # Logic
    if state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    if pos == 0:
        if should_enter_long():
            state['position'] = position_size()
            state['stop_price'] = atr_level(-STOP_ATR * atr_value())
            state['target_price'] = atr_level(TARGET_ATR * atr_value())
            state['box_high'] = hist.high[-1]
            state['box_low'] = hist.low[-1]
            return {"target": state['position'], "stop": state['stop_price'], "take": state['target_price']}
        elif should_enter_short():
            state['position'] = -position_size()
            state['stop_price'] = atr_level(STOP_ATR * atr_value())
            state['target_price'] = atr_level(-TARGET_ATR * atr_value())
            state['box_high'] = hist.high[-1]
            state['box_low'] = hist.low[-1]
            return {"target": state['position'], "stop": state['stop_price'], "take": state['target_price']}

    if should_close():
        state['position'] = 0
        state['stop_price'] = None
        state['target_price'] = None
        state['box_high'] = hist.high[-1]
        state['box_low'] = hist.low[-1]
        state['cooldown'] = COOLDOWN_PERIOD
        return {"target": state['position'], "stop": None, "take": None}

    if should_ratchet():
        state['box_high'] = hist.high[-1]
        state['box_low'] = hist.low[-1]
        state['stop_price'] = atr_level(-STOP_ATR * atr_value())
        state['target_price'] = atr_level(TARGET_ATR * atr_value())

    if should_flip():
        state['position'] = -state['position']
        state['stop_price'] = atr_level(-STOP_ATR * atr_value())
        state['target_price'] = atr_level(TARGET_ATR * atr_value())

    return {"target": state['position'], "stop": state['stop_price'], "take": state['target_price']}

