    MAX_ENTRIES_PER_DAY = 3
    POSITION_SIZE = 0.25
    ADDITIONAL_POSITION_SIZE = 0.25
    MAX_ADDITIONS = 2

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate entry ATR
    entry_atr = ind.atr(hist, LOOKBACK)[-1]

    # Calculate Donchian channels
    upper_channel = ind.highest(hist.high, LOOKBACK)[-1]
    lower_channel = ind.lowest(hist.low, LOOKBACK)[-1]

    # Determine potential entry signals
    long_entry = current_bar.close > upper_channel and previous_bar.close <= upper_channel
    short_entry = current_bar.close < lower_channel and previous_bar.close >= lower_channel

    # Determine if we are in a trade
    in_trade = pos != 0

    # Determine if it's time to close the trade due to time stop
    if in_trade and hist.time[-1] - hist.time[-TIME_STOP_BARS - 1] >= TIME_STOP_BARS * 15 * 60 * 1000:
        return {"target": 0, "stop": None, "take": None}

    # Determine if it's time to close the trade due to profit
    if in_trade:
        if pos > 0 and current_bar.high >= previous_bar.high + entry_atr * TAKE_PROFIT_ATR:
            return {"target": 0, "stop": None, "take": None}
        if pos < 0 and current_bar.low <= previous_bar.low - entry_atr * TAKE_PROFIT_ATR:
            return {"target": 0, "stop": None, "take": None}

    # Determine if we need to add to the trade
    if in_trade and pos > 0 and current_bar.close >= previous_bar.close + entry_atr * ENTRY_ATR:
        if state.get("additions", 0) < MAX_ADDITIONS:
            state["additions"] += 1
            return {"target": pos + ADDITIONAL_POSITION_SIZE, "stop": None, "take": None}
    if in_trade and pos < 0 and current_bar.close <= previous_bar.close - entry_atr * ENTRY_ATR:
        if state.get("additions", 0) < MAX_ADDITIONS:
            state["additions"] += 1
            return {"target": pos - ADDITIONAL_POSITION_SIZE, "stop": None, "take": None}

    # Determine if we need to open a new trade
    if not in_trade and (long_entry or short_entry):
        if state.get("entries_today", 0) < MAX_ENTRIES_PER_DAY:
            state["entries_today"] += 1
            if long_entry:
                return {"target": POSITION_SIZE, "stop": None, "take": None}
            if short_entry:
                return {"target": -POSITION_SIZE, "stop": None, "take": None}

