        position_size = (risk_percent * close) / (2 * atr)
        position_size = max(position_size, risk_floor)
        position_size = min(position_size, risk_cap)
        return position_size

    def calculate_target_price(hist, atr, position_size):
        return hist.close[-1] + (position_size * atr)

    def calculate_stop_price(hist, atr, position_size):
        return hist.close[-1] - (position_size * atr)

    # State management
    if 'armed' not in state:
        state['armed'] = False
    if 'armed_high' not in state:
        state['armed_high'] = None
    if 'armed_low' not in state:
        state['armed_low'] = None
    if 'armed_bar' not in state:
        state['armed_bar'] = None
    if 'last_trade_bar' not in state:
        state['last_trade_bar'] = None

