    target_price = calculate_target_price(hist, atr, position_size)
    stop_price = calculate_stop_price(hist, atr, position_size)

    # Determine if we are in a cooldown period
    if state['last_trade_bar'] is not None and len(hist) - state['last_trade_bar'] < COOLDOWN_BARS:
        return {"target": pos, "stop": None, "take": None}

    # Determine if we are armed
    if not state['armed']:
        # Check for breakout
        high = ind.highest(hist.high, DONCHIAN_PERIOD)[-1]
        low = ind.lowest(hist.low, DONCHIAN_PERIOD)[-1]
        if hist.close[-1] > high:
            state['armed'] = True
            state['armed_high'] = high
            state['armed_low'] = None
            state['armed_bar'] = len(hist) - 1
        elif hist.close[-1] < low:
            state['armed'] = True
            state['armed_high'] = None
            state['armed_low'] = low
            state['armed_bar'] = len(hist) - 1
    else:
        # Check if we are in the arm period
        if len(hist) - state['armed_bar'] < ARM_PERIOD:
            return {"target": pos, "stop": None, "take": None}
        else:
            # Check if the breakout level is still valid
            if state['armed_high'] is not None and hist.close[-1] <= state['armed_high']:
