                state['armed_high'] = None
                state['armed_low'] = None
                state['armed_bar'] = None
            elif state['armed_low'] is not None and hist.close[-1] >= state['armed_low']:
                state['armed'] = False
                state['armed_high'] = None
                state['armed_low'] = None
                state['armed_bar'] = None

    # Determine the target and stop prices based on the current position
    if pos > 0:
        target_price = state['armed_high'] if state['armed_high'] is not None else target_price
        stop_price = state['armed_low'] if state['armed_low'] is not None else stop_price
    elif pos < 0:
