import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    MACD_FAST = 12
    MACD_SLOW = 26
    MACD_SIGNAL = 9
    ENTRY_ATR_PERIOD = 14
    STOP_TRAIL_ATR = 3
    ENTRY_ATR_CAP = 0.03
    MAX_TRADES_PER_DAY = 3
    ENTRY_EMA_PERIOD = 50
    ENTRY_EMA_HTF_PERIOD = 60
    POSITION_SIZE = 0.25

    # Get current bar and previous bar
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, MACD_FAST, MACD_SLOW, MACD_SIGNAL)
    macd_cross = (macd_line[-1] > signal_line[-1]) and (macd_line[-2] <= signal_line[-2])

    # Calculate entry EMA
    entry_ema = ind.ema(hist.close, ENTRY_EMA_PERIOD)
    entry_ema_htf = ind.ema(hist.htf(ENTRY_EMA_HTF_PERIOD).close, ENTRY_EMA_PERIOD)

    # Check if we are flat and the 1h close is above the 50 EMA
    if pos == 0 and current_bar.close > entry_ema_htf[-1]:
        # Check if we have already made the maximum number of trades today
        if 'trade_count' not in state or state['trade_count'] < MAX_TRADES_PER_DAY:
            # Calculate entry price and ATR
            entry_price = current_bar.close
            entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

            # Calculate position size
            position_size = min(POSITION_SIZE, entry_price / (entry_atr * ENTRY_ATR_CAP))

            # Calculate stop price
            stop_price = entry_price - STOP_TRAIL_ATR * entry_atr

            # Update state
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['stop_price'] = stop_price
            state['trade_count'] = state.get('trade_count', 0) + 1

            return {"target": position_size, "stop": stop_price, "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}
    else:
        # Check if we need to close the trade
        if pos != 0:
            if macd_cross:
                return {"target": 0, "stop": None, "take": None}
            elif current_bar.high >= state['entry_price'] + 3 * state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            elif current_bar.low <= state['stop_price']:
                return {"target": 0, "stop": None, "take": None}
            else:
                return {"target": pos, "stop": state['stop_price'], "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}

