def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR_PERIOD = 14
    CHANNEL_PERIOD = 48
    MAX_ADDS = 3
    COOLDOWN_PERIOD = 256
    POSITION_FRACTION = 0.25
    ADD_THRESHOLD_ATR = 2
    MAX_POSITION_FRACTION = 1.0

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate entry ATR and Donchian channel
    entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
    upper_channel = ind.highest(hist.high, CHANNEL_PERIOD)[-1]
    lower_channel = ind.lowest(hist.low, CHANNEL_PERIOD)[-1]

    # Determine if we are flat or in a trade
    if pos == 0:
        # Check for long entry
        if current_bar.close > upper_channel:
            state['entry_price'] = current_bar.close
            state['entry_atr'] = entry_atr
            state['add_count'] = 0
            state['cooldown'] = 0
            return {"target": POSITION_FRACTION, "stop": None, "take": None}
        # Check for short entry
        elif current_bar.close < lower_channel:
            state['entry_price'] = current_bar.close
            state['entry_atr'] = entry_atr
            state['add_count'] = 0
            state['cooldown'] = 0
            return {"target": -POSITION_FRACTION, "stop": None, "take": None}
    else:
        # Check for exit conditions
        if state['cooldown'] > 0:
            state['cooldown'] -= 1
            return {"target": pos, "stop": None, "take": None}
        if len(hist) - state['entry_price'] / 1000 >= COOLDOWN_PERIOD:
            return {"target": 0, "stop": None, "take": None}
        if pos > 0:
            if current_bar.low <= state['entry_price'] - state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            if current_bar.high >= state['entry_price'] + state['entry_atr'] * (1 + ADD_THRESHOLD_ATR * state['add_count']):
                state['add_count'] += 1
                return {"target": min(pos + POSITION_FRACTION, MAX_POSITION_FRACTION), "stop": None, "take": None}
        else:
            if current_bar.high >= state['entry_price'] + state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            if current_bar.low <= state['entry_price'] - state['entry_atr'] * (1 + ADD_THRESHOLD_ATR * state['add_count']):
                state['add_count'] += 1
                return {"target": max(pos - POSITION_FRACTION, -MAX_POSITION_FRACTION), "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}

