def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR_PERIOD = 14
    COOLDOWN_PERIOD = 48
    ENTRY_SIZE = 0.25
    MAX_ADD_SIZE = 0.25
    HARD_STOP_ATR = 1.5
    TAKE_PROFIT_ATR = 0.5
    RISK_PER_ATR = 0.01
    K_ATR = 5

    # Helper functions
    def get_entry_price():
        return hist.close[-1]

    def get_entry_atr():
        return ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    def get_ema(x, n):
        return ind.ema(x, n)[-1]

    def get_highest(x, n):
        return ind.highest(x, n)[-1]

    def get_lowest(x, n):
        return ind.lowest(x, n)[-1]

    # State management
    if 'last_cross' not in state:
        state['last_cross'] = None
    if 'last_add' not in state:
        state['last_add'] = None
    if 'last_stop' not in state:
        state['last_stop'] = None

    # Entry conditions
    if pos == 0 and state['last_cross'] is None:
        ema_5 = get_ema(hist.close, 5)
        ema_50 = get_ema(hist.close, 50)
        htf_4h_close = hist.htf(240).close[-1]
        htf_4h_ema_50 = get_ema(hist.htf(240).close, 50)

        if htf_4h_close > htf_4h_ema_50 and ema_5 > ema_50:
            state['last_cross'] = 'long'
            state['last_add'] = None
            state['last_stop'] = None
            entry_price = get_entry_price()
            entry_atr = get_entry_atr()
            target = ENTRY_SIZE * RISK_PER_ATR * entry_price / (K_ATR * entry_atr)
            stop = entry_price - HARD_STOP_ATR * entry_atr
            return {"target": target, "stop": stop, "take": None}
        elif htf_4h_close < htf_4h_ema_50 and ema_5 < ema_50:
            state['last_cross'] = 'short'
            state['last_add'] = None
            state['last_stop'] = None
            entry_price = get_entry_price()
            entry_atr = get_entry_atr()
            target = -ENTRY_SIZE * RISK_PER_ATR * entry_price / (K_ATR * entry_atr)
            stop = entry_price + HARD_STOP_ATR * entry_atr
            return {"target": target, "stop": stop, "take": None}

    # Exit conditions
    if pos != 0:
        if state['last_cross'] == 'long':
            if hist.low[-1] <= state['last_stop']:
                return {"target": 0, "stop": None, "take": None}
            if hist.high[-1] >= get_entry_price() + TAKE_PROFIT_ATR * get_entry_atr():
                state['last_stop'] = get_entry_price()
                return {"target": pos, "stop": state['last_stop'], "take": None}
        elif state['last_cross'] == 'short':
            if hist.high[-1] >= state['last_stop']:
                return {"target": 0, "stop": None, "take": None}
            if hist.low[-1] <= get_entry_price() - TAKE_PROFIT_ATR * get_entry_atr():
                state['last_stop'] = get_entry_price()
                return {"target": pos, "stop": state['last_stop'], "take": None}

    # Add size conditions
    if pos != 0 and state['last_add'] is not None:
        if state['last_cross'] == 'long':
            if hist.high[-1] >= get_entry_price() + (state['last_add'] + 1) * ENTRY_ATR:
                state['last_add'] += 0.25
                target = pos + 0.25
                stop = state['last_stop']
                return {"target": target, "stop": stop, "take": None}
        elif state['last_cross'] == 'short':
            if hist.low[-1] <= get_entry_price() - (state['last_add'] + 1) * ENTRY_ATR:
                state['last_add'] += 0.25
                target = pos - 0.25
                stop = state['last_stop']
                return {"target": target, "stop": stop, "take": None}

    # Cool down conditions
    if pos != 0 and state['last_cross'] is not None:
        if len(hist) - state['last_cross'] > COOLDOWN_PERIOD:
            state['last_cross'] = None
            state['last_add'] = None
            state['last_stop'] = None

    return {"target": pos, "stop": None, "take": None}

