def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RSI_OVERSOLD = 30
    RSI_OVERBOUGHT = 70
    ATR_PERIOD = 14
    VOLATILITY_RISK = 0.005
    VOLATILITY_K = 3
    STOP_ATR = 1
    TAKE_ATR = 3
    MAX_TRADES_PER_DAY = 3
    COOLDOWN_HOURS = 4
    ENTRY_EMA_PERIOD = 20
    HIGHER_TIMEFRAME = 60

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Get RSI and ATR
    rsi = ind.rsi(hist.close, ATR_PERIOD)
    atr = ind.atr(hist, ATR_PERIOD)

    # Get higher timeframe data
    htf_close = hist.htf(HIGHER_TIMEFRAME).close
    htf_ema = ind.ema(htf_close, ENTRY_EMA_PERIOD)

    # Determine if we are in a cooldown period
    if 'last_flat_time' in state and current_bar.time - state['last_flat_time'] < COOLDOWN_HOURS * 3600 * 1000:
        return {"target": pos, "stop": None, "take": None}

    # Determine if we are flat
    if pos == 0:
        # Check for long entry
        if rsi[-1] < RSI_OVERSOLD and current_bar.close > htf_ema[-1]:
            # Calculate position size
            position_size = VOLATILITY_RISK * current_bar.close / (VOLATILITY_K * atr[-1])
            position_size = max(0.05, min(1.0, position_size))
            # Set state variables
            state['last_flat_time'] = current_bar.time
            state['entry_price'] = current_bar.close
            state['entry_atr'] = atr[-1]
            state['trades_today'] = state.get('trades_today', 0) + 1
            if state['trades_today'] >= MAX_TRADES_PER_DAY:
                return {"target": pos, "stop": None, "take": None}
            return {"target": position_size, "stop": None, "take": None}
        # Check for short entry
        elif rsi[-1] > RSI_OVERBOUGHT and current_bar.close < htf_ema[-1]:
            # Calculate position size
            position_size = VOLATILITY_RISK * current_bar.close / (VOLATILITY_K * atr[-1])
            position_size = max(0.05, min(1.0, position_size))
            # Set state variables
            state['last_flat_time'] = current_bar.time
            state['entry_price'] = current_bar.close
            state['entry_atr'] = atr[-1]
            state['trades_today'] = state.get('trades_today', 0) + 1
            if state['trades_today'] >= MAX_TRADES_PER_DAY:
                return {"target": pos, "stop": None, "take": None}
            return {"target": -position_size, "stop": None, "take": None}
    else:
        # Check for exit conditions
        if pos > 0:
            # Check for stop loss
            if current_bar.low <= state['entry_price'] - STOP_ATR * state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            # Check for take profit
            if current_bar.high >= state['entry_price'] + TAKE_ATR * state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            # Check for trailing stop
            if current_bar.high >= state['entry_price'] + (state['entry_price'] - state['last_stop_price']) + STOP_ATR * state['entry_atr']:
                state['last_stop_price'] = current_bar.high
                return {"target": pos, "stop": state['last_stop_price'], "take": None}
        else:
            # Check for stop loss
            if current_bar.high >= state['entry_price'] + STOP_ATR * state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            # Check for take profit
            if current_bar.low <= state['entry_price'] - TAKE_ATR * state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            # Check for trailing stop
            if current_bar.low <= state['entry_price'] - (state['entry_price'] - state['last_stop_price']) - STOP_ATR * state['entry_atr']:
                state['last_stop_price'] = current_bar.low
                return {"target": pos, "stop": state['last_stop_price'], "take": None}
    return {"target": pos, "stop": None, "take": None}

