    if 'last_add' not in state:
        state['last_add'] = 0
    if 'last_cooldown' not in state:
        state['last_cooldown'] = 0

    # RSI crossover signals
    rsi = ind.rsi(hist.close, ATR_PERIOD)[-1]
    long_signal = rsi < RSI_OVERSOLD and hist.close[-1] > ENTRY_EMA
    short_signal = rsi > RSI_OVERBOUGHT and hist.close[-1] < ENTRY_EMA

    # Cooldown check
    if state['last_cooldown'] > 0:
        state['last_cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Exit conditions
    if pos != 0 and (hist.close[-1] <= hist.open[-1] or hist.close[-1] >= hist.open[-1]):
        return {"target": 0, "stop": None, "take": None}

