    if long_signal and state['last_signal'] != 'long':
        state['last_signal'] = 'long'
        state['last_add'] = 0
        state['last_cooldown'] = COOLDOWN_PERIOD
        return {"target": QUARTER_SIZE, "stop": None, "take": None}
    elif short_signal and state['last_signal'] != 'short':
        state['last_signal'] = 'short'
        state['last_add'] = 0
        state['last_cooldown'] = COOLDOWN_PERIOD
