    def get_bullish_level(hist, breakout_index):
        return ind.highest(hist.low, BREAKOUT_PERIOD)[breakout_index]

    def get_bearish_level(hist, breakout_index):
        return ind.lowest(hist.high, BREAKOUT_PERIOD)[breakout_index]

    # Check for breakout
    if 'breakout_index' not in state:
        breakout_index = -1
    else:
        breakout_index = state['breakout_index']

    if breakout_index == -1:
        if hist.high[-1] > ind.highest(hist.high, BREAKOUT_PERIOD)[-1]:
            breakout_index = len(hist) - 1
            state['breakout_index'] = breakout_index
            state['bullish'] = True
            state['bearish'] = False
        elif hist.low[-1] < ind.lowest(hist.low, BREAKOUT_PERIOD)[-1]:
            breakout_index = len(hist) - 1
            state['breakout_index'] = breakout_index
            state['bullish'] = False
            state['bearish'] = True

    if breakout_index == -1:
        return {"target": pos, "stop": None, "take": None}

    # Check for retest
    if state['bullish']:
        if hist.low[-1] <= get_bullish_level(hist, breakout_index):
            return {"target": POSITION_SIZE, "stop": hist.close[-1] - STOP_AWAY_ATR * get_entry_atr(hist, breakout_index), "take": None}
    elif state['bearish']:
        if hist.high[-1] >= get_bearish_level(hist, breakout_index):
            return {"target": -POSITION_SIZE, "stop": hist.close[-1] + STOP_AWAY_ATR * get_entry_atr(hist, breakout_index), "take": None}

    # Check for signal to close
    if state['bullish']:
        if ind.ema(hist.close, LONG_SIGNAL_EMA_PERIOD)[-1] < ind.ema(hist.close, SHORT_SIGNAL_EMA_PERIOD)[-1]:
            return {"target": 0, "stop": None, "take": None}
    elif state['bearish']:
        if ind.ema(hist.close, LONG_SIGNAL_EMA_PERIOD)[-1] > ind.ema(hist.close, SHORT_SIGNAL_EMA_PERIOD)[-1]:
            return {"target": 0, "stop": None, "take": None}

    # Check for signal to flip
    if state['bullish']:
        if ind.ema(hist.close, LONG_SIGNAL_EMA_PERIOD)[-1] < ind.ema(hist.close, SHORT_SIGNAL_EMA_PERIOD)[-1]:
