    hist_4h = hist.htf(240)
    ema_4h = ind.ema(hist_4h.close, EMA_4H_PERIOD)[-1]

    # Calculate box range
    box_high = ind.highest(hist.close, BOX_PERIOD)[-1]
    box_low = ind.lowest(hist.close, BOX_PERIOD)[-1]
    box_height = box_high - box_low

    # Check if box height is at most 3 times ATR
    if box_height > 3 * atr:
        return {"target": pos, "stop": None, "take": None}

    # Check 4-hour trend
    if hist_4h.close[-1] > ema_4h:
        trend = "long"
    elif hist_4h.close[-1] < ema_4h:
        trend = "short"
    else:
        return {"target": pos, "stop": None, "take": None}

    # Check if we are already in a trade
    if pos != 0:
        # Check for time stop
        if state.get("time_stop", 0) + TIME_STOP_BARS <= t:
            return {"target": 0, "stop": None, "take": None}

