            return {"target": 0, "stop": None, "take": None}

        return {"target": pos, "stop": None, "take": None}

    # Check if we can open a new trade
    if state.get("trades_today", 0) >= MAX_TRADES_PER_DAY:
        return {"target": pos, "stop": None, "take": None}

    # Open new trade
    if trend == "long":
        target = 1
        stop = box_low
        take = box_high + TP_ATR * atr
    elif trend == "short":
        target = -1
        stop = box_high
        take = box_low - TP_ATR * atr

    # Update state
    state["trades_today"] = state.get("trades_today", 0) + 1
    state["time_stop"] = t

    return {"target": target, "stop": stop, "take": take}

