def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    EMA_10 = 10
    EMA_50 = 50
    EMA_20 = 20
    TP_ATRS = 2
    COOLDOWN_BARS = 16
    POSITION_SIZE = 1.0

    # Get current and previous bars
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate EMAs
    ema_10 = ind.ema(hist.close, EMA_10)[-1]
    ema_50 = ind.ema(hist.close, EMA_50)[-1]
    ema_20 = ind.ema(hist.close, EMA_20)[-1]

    # Check for trend direction
    if ema_10 > ema_50 and ema_20 > ema_50:
        trend = 'long'
    elif ema_10 < ema_50 and ema_20 < ema_50:
        trend = 'short'
    else:
        trend = 'flat'

    # Check for entry conditions
    if trend == 'long':
        if previous_bar.close > ind.ema(hist.close, EMA_20)[-2]:
            if pos == 0:
                entry_price = current_bar.close
                atr = ind.atr(hist, ATR_PERIOD)[-1]
                target = POSITION_SIZE
                stop = entry_price - atr * TP_ATRS
                take = entry_price + atr * TP_ATRS
                state['cooldown'] = COOLDOWN_BARS
                return {"target": target, "stop": stop, "take": take}
    elif trend == 'short':
        if previous_bar.close < ind.ema(hist.close, EMA_20)[-2]:
            if pos == 0:
                entry_price = current_bar.close
                atr = ind.atr(hist, ATR_PERIOD)[-1]
                target = -POSITION_SIZE
                stop = entry_price + atr * TP_ATRS
                take = entry_price - atr * TP_ATRS
                state['cooldown'] = COOLDOWN_BARS
                return {"target": target, "stop": stop, "take": take}

    # Check for exit conditions
    if pos != 0:
        if state.get('cooldown', 0) > 0:
            state['cooldown'] -= 1
        else:
            if trend == 'long' and current_bar.low <= pos * ind.atr(hist, ATR_PERIOD)[-1]:
                return {"target": 0}
            elif trend == 'short' and current_bar.high >= pos * ind.atr(hist, ATR_PERIOD)[-1]:
                return {"target": 0}

    # No change
    return {"target": pos}

