    current_bar = -1
    signal_bar = -2
    entry_price = hist.close[signal_bar]
    entry_atr = ind.atr(hist, 14)[signal_bar]
    max_trades_per_day = 2
    trades_today = state.get('trades_today', 0)

    if pos == 0:
        if hist.close[current_bar] > ind.highest(hist.close, 48)[signal_bar]:
            if trades_today < max_trades_per_day:
                state['trades_today'] = trades_today + 1
