def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 336:  # 960 bars + 240 bars for cooldown
        return {"target": pos, "stop": None, "take": None}

    current_bar = len(hist) - 1
    signal_bar = current_bar - 32

    # Calculate the 32-bar high box
    box_high = ind.highest(hist.high, 32)
    box_height = box_high[current_bar] - hist.low[signal_bar]

    # Check for breakout condition
    if hist.close[current_bar] > box_high[current_bar] and box_height <= 6 * ind.atr(hist, 14)[signal_bar]:
        if 'last_fill' not in state or current_bar - state['last_fill'] >= 16:
            entry_price = hist.close[current_bar]
            entry_atr = ind.atr(hist, 14)[signal_bar]
            target_size = 0.5 * entry_price / (1 * entry_atr)
            target_size = min(target_size, 1.0)
            state['last_fill'] = current_bar
            state['target_size'] = target_size
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            return {"target": target_size, "stop": None, "take": entry_price + 4 * entry_atr}

    # Check for pyramid condition
    if 'last_fill' in state and current_bar - state['last_fill'] >= 16:
        if hist.close[current_bar] >= state['entry_price'] + state['entry_atr']:
            target_size = state['target_size'] + 0.5 * state['entry_price'] / (1 * state['entry_atr'])
            target_size = min(target_size, 1.0)
            state['target_size'] = target_size
            return {"target": target_size, "stop": None, "take": state['entry_price'] + 4 * state['entry_atr']}

    # Check for opposite breakdown signal
    if hist.close[current_bar] < state['entry_price']:
        return {"target": 0, "stop": None, "take": None}

    # Check for 16-bar cooldown
    if 'last_fill' in state and current_bar - state['last_fill'] < 16:
        return {"target": pos, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

