def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    ENTRY_SMA_FAST = 20
    ENTRY_SMA_SLOW = 100
    ENTRY_ATR_MULTIPLIER = 0.5
    MAX_TRADES_PER_DAY = 3
    TRAILING_STOP_ATR_MULTIPLIER = 3
    PYRAMID_CHUNK = 0.5
    MAX_POSITION_SIZE = 1.0

    # Get current bar data
    current_close = hist.close[-1]
    current_high = hist.high[-1]
    current_low = hist.low[-1]
    current_time = hist.time[-1]

    # Calculate SMAs
    fast_sma = ind.sma(hist.close, ENTRY_SMA_FAST)[-1]
    slow_sma = ind.sma(hist.close, ENTRY_SMA_SLOW)[-1]

    # Determine entry signal
    if fast_sma > slow_sma and pos == 0:
        entry_price = current_close
        entry_atr = ind.atr(hist, ATR_PERIOD)[-1]
        target_size = ENTRY_ATR_MULTIPLIER * entry_price / (entry_atr * 2)  # Half size
        target_size = min(target_size, MAX_POSITION_SIZE)
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['entry_time'] = current_time
        state['trades_today'] = state.get('trades_today', 0) + 1
        return {"target": target_size, "stop": None, "take": None}
    elif fast_sma < slow_sma and pos == 0:
        entry_price = current_close
        entry_atr = ind.atr(hist, ATR_PERIOD)[-1]
        target_size = ENTRY_ATR_MULTIPLIER * entry_price / (entry_atr * 2)  # Half size
        target_size = min(target_size, MAX_POSITION_SIZE)
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['entry_time'] = current_time
        state['trades_today'] = state.get('trades_today', 0) + 1
        return {"target": -target_size, "stop": None, "take": None}
    elif pos != 0 and state['trades_today'] >= MAX_TRADES_PER_DAY:
        return {"target": 0, "stop": None, "take": None}

    # Determine exit signals
    if pos > 0:
        trailing_stop = state['entry_price'] - state['entry_atr'] * TRAILING_STOP_ATR_MULTIPLIER
        take_profit = state['entry_price'] + state['entry_atr'] * 2
        if current_low <= trailing_stop:
            return {"target": 0, "stop": None, "take": None}
        elif current_high >= take_profit:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        trailing_stop = state['entry_price'] + state['entry_atr'] * TRAILING_STOP_ATR_MULTIPLIER
        take_profit = state['entry_price'] - state['entry_atr'] * 2
        if current_high >= trailing_stop:
            return {"target": 0, "stop": None, "take": None}
        elif current_low <= take_profit:
            return {"target": 0, "stop": None, "take": None}

    # Determine pyramid signals
    if pos > 0 and current_high >= state['entry_price'] + state['entry_atr'] * 2:
        new_target = pos + PYRAMID_CHUNK
        new_target = min(new_target, MAX_POSITION_SIZE)
        return {"target": new_target, "stop": None, "take": None}
    elif pos < 0 and current_low <= state['entry_price'] - state['entry_atr'] * 2:
        new_target = pos - PYRAMID_CHUNK
        new_target = max(new_target, -MAX_POSITION_SIZE)
        return {"target": new_target, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

