import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    COOLDOWN_BARS = 4
    SIGNAL_BARS = 16
    RISK_PERCENT = 0.01
    ATR_PERIOD = 14
    LONG_SIGNAL = 1
    SHORT_SIGNAL = -1
    NO_SIGNAL = 0
    POSITION_CAP = 1.0
    POSITION_FLOOR = 0.05

    # Helper functions
    def get_entry_price(signal):
        return hist.close[signal]

    def get_entry_atr(signal):
        return ind.atr(hist, ATR_PERIOD)[signal]

    def get_position_size(entry_price, entry_atr):
        return max(POSITION_FLOOR, min(POSITION_CAP, RISK_PERCENT * entry_price / (entry_atr * 1)))

    # State management
    if 'last_signal' not in state:
        state['last_signal'] = NO_SIGNAL
    if 'last_signal_bar' not in state:
        state['last_signal_bar'] = -1
    if 'cooldown_counter' not in state:
        state['cooldown_counter'] = 0

    # Determine signal
    current_bar = len(hist) - 1
    if current_bar < 192:
        signal = NO_SIGNAL
    else:
        high_192 = ind.highest(hist.high, 192)[current_bar]
        low_192 = ind.lowest(hist.low, 192)[current_bar]
        if hist.close[current_bar] > high_192:
            signal = LONG_SIGNAL
        elif hist.close[current_bar] < low_192:
            signal = SHORT_SIGNAL
        else:
            signal = NO_SIGNAL

    # Cooldown logic
    if signal != NO_SIGNAL and signal != state['last_signal']:
        state['last_signal'] = signal
        state['last_signal_bar'] = current_bar
        state['cooldown_counter'] = COOLDOWN_BARS
    elif signal == NO_SIGNAL:
        state['cooldown_counter'] = max(0, state['cooldown_counter'] - 1)

    # Position sizing
    if signal == LONG_SIGNAL:
        entry_price = get_entry_price(current_bar)
        entry_atr = get_entry_atr(current_bar)
        target = get_position_size(entry_price, entry_atr)
    elif signal == SHORT_SIGNAL:
        entry_price = get_entry_price(current_bar)
        entry_atr = get_entry_atr(current_bar)
        target = -get_position_size(entry_price, entry_atr)
    else:
        target = pos

    # Exit conditions
    if current_bar - state['last_signal_bar'] >= SIGNAL_BARS:
        target = 0

    # Stop and take levels
    if signal == LONG_SIGNAL:
        stop = hist.low[current_bar] - 2 * get_entry_atr(state['last_signal_bar'])
        take = hist.high[current_bar] + 1 * get_entry_atr(state['last_signal_bar'])
    elif signal == SHORT_SIGNAL:
        stop = hist.high[current_bar] + 2 * get_entry_atr(state['last_signal_bar'])
        take = hist.low[current_bar] - 1 * get_entry_atr(state['last_signal_bar'])
    else:
        stop = None
        take = None

    return {"target": target, "stop": stop, "take": take}

