        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    high_96 = ind.highest(hist.high, 96)
    low_96 = ind.lowest(hist.low, 96)

    if hist.close[-1] > high_96[-1]:
        direction = 1
        retest_level = high_96[-1] + 2 * ind.atr(hist, 14)[-1]
    elif hist.close[-1] < low_96[-1]:
        direction = -1
        retest_level = low_96[-1] - 2 * ind.atr(hist, 14)[-1]
    else:
        return {"target": pos, "stop": None, "take": None}

    if 'retest_level' in state and state['retest_level'] != retest_level:
        state['retest_level'] = retest_level
        state['retest_expiry'] = len(hist) + 32

    if 'retest_expiry' in state and state['retest_expiry'] <= len(hist):
        state['retest_level'] = None
        state['retest_expiry'] = None

    if 'retest_level' in state and state['retest_level'] is not None:
        if direction == 1 and hist.low[-1] <= state['retest_level']:
            if ind.ema(hist.close.htf(60), 20)[-1] > hist.close[-1]:
                atr = ind.atr(hist, 14)[-1]
                target = min(max(0.05, 0.01 * hist.close[-1] / (2 * atr)), 1.0)
                stop = state['retest_level']
                take = state['retest_level'] + 2 * atr
                state['cooldown'] = 96
                return {"target": target, "stop": stop, "take": take}
        elif direction == -1 and hist.high[-1] >= state['retest_level']:
            if ind.ema(hist.close.htf(60), 20)[-1] < hist.close[-1]:
                atr = ind.atr(hist, 14)[-1]
                target = max(-1.0, -0.01 * hist.close[-1] / (2 * atr))
                stop = state['retest_level']
                take = state['retest_level'] - 2 * atr
                state['cooldown'] = 96
                return {"target": target, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

