        elif pos < 0:
            return {"target": 0, "stop": None, "take": None}
    elif hist.close[current_bar] < box_bottom:
        if pos == 0:
            target = -0.75 * hist.close[current_bar] / (75 * atr_14)
            stop = box_bottom + atr_14
            take = box_bottom - 1.5 * atr_14
            return {"target": target, "stop": stop, "take": take}
