    MIN_SIZE = 0.05
    MAX_SIZE = 1.0
    TIMEFRAME = 60  # 1 hour in minutes

    # Helper functions
    def atr(hist, period):
        return ind.atr(hist, period)[-1]

    def box_high(hist, period):
        return ind.highest(hist.high, period)[-1]

    def box_low(hist, period):
        return ind.lowest(hist.low, period)[-1]

    def ema(hist, period):
        return ind.ema(hist.close, period)[-1]

    def is_flat():
        return pos == 0

    def is_new_day():
        return state.get('last_trade_time', 0) != hist.time[-1] // (24 * 60 * 60 * 1000)

    def update_last_trade_time():
        state['last_trade_time'] = hist.time[-1]

    def calculate_size(entry_price, atr):
        size = RISK_PER_ATR * entry_price / (2 * atr)
        return max(MIN_SIZE, min(MAX_SIZE, size))

    # Check if it's a new day and reset trade count if necessary
    if is_new_day():
        state['trade_count'] = 0
        update_last_trade_time()

    # Check if the trade count limit is reached
    if state.get('trade_count', 0) >= MAX_TRADES_PER_DAY:
        return {"target": pos, "stop": None, "take": None}

    # Calculate ATR and box levels
    entry_atr = atr(hist, ATR_PERIOD)
    box_high_level = box_high(hist, BOX_PERIOD)
    box_low_level = box_low(hist, BOX_PERIOD)

    # Check for breakout conditions
    if hist.close[-1] > box_high_level and hist.close[-2] <= box_high_level:
        if hist.close[-1] - box_high_level <= 6 * entry_atr and is_flat():
            entry_price = hist.close[-1]
            size = calculate_size(entry_price, entry_atr)
            state['trade_count'] += 1
            update_last_trade_time()
            return {"target": size, "stop": box_high_level - 2 * entry_atr, "take": box_high_level + 2 * entry_atr}
    elif hist.close[-1] < box_low_level and hist.close[-2] >= box_low_level:
        if box_low_level - hist.close[-1] <= 6 * entry_atr and is_flat():
            entry_price = hist.close[-1]
            size = calculate_size(entry_price, entry_atr)
            state['trade_count'] += 1
            update_last_trade_time()
            return {"target": -size, "stop": box_low_level + 2 * entry_atr, "take": box_low_level - 2 * entry_atr}

    # Check for trend filter
    if hist.time[-1] % (24 * 60 * 60 * 1000) >= 60 * 60 * 1000:  # Check if it's within the last hour
        if hist.close[-1] > ema(hist.htf(TIMEFRAME), 50):
            return {"target": pos, "stop": None, "take": None}
        elif hist.close[-1] < ema(hist.htf(TIMEFRAME), 50):
            return {"target": pos, "stop": None, "take": None}

