            state['stop'] = round_to_grid(pos + TRAILING_STOP_ATR * state['entry_atr'])
            state['take'] = round_to_grid(pos - TARGET_ATR * state['entry_atr'])
            return {"target": state['target'], "stop": state['stop'], "take": state['take']}

