    if 'last_entry_time' not in state:
        state['last_entry_time'] = current_bar.time
        state['entry_count'] = 0
    elif current_bar.time - state['last_entry_time'] >= 24 * 60 * 60 * 1000:
        state['last_entry_time'] = current_bar.time
        state['entry_count'] = 0

    # Check if the entry count is within the limit
    if state['entry_count'] >= MAX_NEW_ENTRIES_PER_DAY:
        return {"target": pos, "stop": None, "take": None}

    # Check for a new long entry
    if pos == 0 and ema_20 > ema_50:
        # Calculate ATR and position size
        atr = ind.atr(hist, 14)[-1]
        position_size = RISK_PER_ATR * current_bar.close / (2 * atr)
        position_size = max(MIN_POSITION, min(MAX_POSITION, position_size))

        # Update state
        state['entry_count'] += 1
        state['entry_price'] = current_bar.close
        state['entry_atr'] = atr

        return {"target": position_size, "stop": None, "take": None}

    # Check for a new short entry
    if pos == 0 and ema_20 < ema_50:
        # Calculate ATR and position size
        atr = ind.atr(hist, 14)[-1]
        position_size = RISK_PER_ATR * current_bar.close / (2 * atr)
        position_size = max(MIN_POSITION, min(MAX_POSITION, position_size))

        # Update state
        state['entry_count'] += 1
        state['entry_price'] = current_bar.close
        state['entry_atr'] = atr

        return {"target": -position_size, "stop": None, "take": None}

    # Check for a hard stop
    if pos > 0 and current_bar.low <= state['entry_price'] - state['entry_atr'] * HARD_STOP_ATR:
