    MAX_TRADES_PER_DAY = 3
    TIMEOUT_BARS = 96
    STOP_ATR_MULTIPLIER = 1
    TAKE_PROFIT_ATR_MULTIPLIER = 2

    # Helper functions
    def is_in_range_box(close, high, low, atr):
        return close > high - ENTRY_ATR_MULTIPLIER * atr and close < low + ENTRY_ATR_MULTIPLIER * atr

    def is_breakout(close, high, low, atr):
        return close > high - ENTRY_ATR_MULTIPLIER * atr

    def is_bearish_breakdown(close, high, low, atr):
        return close < low - ENTRY_ATR_MULTIPLIER * atr

    # Get current bar and previous bars
    current_bar = hist[-1]
    previous_bar = hist[-2]
    atr = ind.atr(hist, ATR_PERIOD)[-1]

    # Check for timeout
    if 'timeout' in state and state['timeout'] > 0:
        state['timeout'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for new trade entry
    if pos == 0:
        # Check for range box
        if is_in_range_box(current_bar.close, current_bar.high, current_bar.low, atr):
            # Check for breakout
            if is_breakout(current_bar.close, previous_bar.high, previous_bar.low, atr):
                # Check for max trades per day
                if 'trades_today' not in state or state['trades_today'] < MAX_TRADES_PER_DAY:
                    # Calculate entry size
                    entry_size = min(ENTRY_SIZE * current_bar.close / (ENTRY_ATR_MULTIPLIER * atr), 1)
                    # Set stop and take profit
                    stop_price = current_bar.close - STOP_ATR_MULTIPLIER * atr
                    take_profit_price = current_bar.close + TAKE_PROFIT_ATR_MULTIPLIER * atr
                    # Update state
                    state['trades_today'] = state.get('trades_today', 0) + 1
                    state['timeout'] = TIMEOUT_BARS
                    return {"target": entry_size, "stop": stop_price, "take": take_profit_price}

    # Check for bearish breakdown
    if pos != 0 and is_bearish_breakdown(current_bar.close, previous_bar.high, previous_bar.low, atr):
        return {"target": 0, "stop": None, "take": None}

    # Check for ratcheting the box
    if pos != 0 and current_bar.close >= state.get('take_profit_price', -math.inf):
        new_take_profit_price = state['take_profit_price'] + atr
        return {"target": pos, "stop": state['stop_price'], "take": new_take_profit_price}

    return {"target": pos, "stop": None, "take": None}

