def strategy(hist, state, pos, ind) -> dict:
    # Constants
    HTF_PERIOD = 240  # 4-hour timeframe in minutes
    TREND_FILTER_PERIOD = 50
    SETUP_PERIOD = 64
    ENTRY_ATR_PERIOD = 14
    MAX_ENTRIES_PER_DAY = 3
    POSITION_SIZE = 0.25
    ADDITION_ATR = 2
    MAX_ADDITIONS = 1

    # Helper functions
    def is_trend_up():
        htf_close = hist.htf(HTF_PERIOD).close
        htf_ema = ind.ema(htf_close, TREND_FILTER_PERIOD)
        return htf_close[-1] > htf_ema[-1]

    def is_new_48_bar_high():
        return hist.close[-1] > ind.highest(hist.close, 48)[-1]

    def is_buy_trigger():
        return hist.low[-1] <= state.get('buy_level', float('-inf'))

    def is_bearish_signal():
        return hist.close[-1] < hist.close[-2]

    def can_enter():
        if pos != 0:
            return False
        if state.get('entries_today', 0) >= MAX_ENTRIES_PER_DAY:
            return False
        return is_trend_up() and is_new_48_bar_high()

    def calculate_position_size():
        entry_price = hist.close[-1]
        entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
        return POSITION_SIZE * entry_price / (SETUP_PERIOD * entry_atr)

    def calculate_addition_size():
        entry_price = hist.close[-1]
        entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
        return POSITION_SIZE * entry_price / (SETUP_PERIOD * entry_atr * (ADDITION_ATR + 1))

    # Main logic
    if can_enter():
        state['entries_today'] = state.get('entries_today', 0) + 1
        state['buy_level'] = hist.close[-1]
        state['position_size'] = calculate_position_size()
        state['addition_size'] = calculate_addition_size()
        state['additions'] = 0
        return {"target": state['position_size'], "stop": None, "take": None}

    if is_buy_trigger():
        if pos < state['position_size']:
            return {"target": pos + state['addition_size'], "stop": None, "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}

    if is_bearish_signal():
        return {"target": 0, "stop": None, "take": None}

    if pos > 0 and state.get('additions', 0) < MAX_ADDITIONS:
        if hist.high[-1] >= state['buy_level'] + state['addition_size'] * (ADDITION_ATR + 1):
            state['additions'] += 1
            return {"target": pos + state['addition_size'], "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

