import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    BREAKOUT_PERIOD = 48
    ARM_PERIOD = 240
    ENTRY_ATR_MULTIPLIER = 2
    TAKE_PROFIT_ATR_MULTIPLIER = 3
    RISK_PERCENTAGE = 0.75
    COOLDOWN_PERIOD = 4

    # Helper functions
    def get_entry_price():
        return hist.close[-1]

    def get_entry_atr():
        return ind.atr(hist, ATR_PERIOD)[-1]

    def get_4h_high():
        return ind.highest(hist.htf(240).high, BREAKOUT_PERIOD)[-1]

    def get_4h_ema():
        return ind.ema(hist.htf(240).close, 50)[-1]

    # State management
    if 'entry_price' not in state:
        state['entry_price'] = None
    if 'entry_atr' not in state:
        state['entry_atr'] = None
    if 'armed' not in state:
        state['armed'] = False
    if 'cooldown' not in state:
        state['cooldown'] = 0

    # Breakout condition
    if state['entry_price'] is None and hist.close[-1] > get_4h_high():
        state['entry_price'] = get_entry_price()
        state['entry_atr'] = get_entry_atr()
        state['armed'] = True
        state['cooldown'] = 0
        return {"target": RISK_PERCENTAGE * state['entry_price'] / (ENTRY_ATR_MULTIPLIER * state['entry_atr']), "stop": None, "take": None}

    # Re-entry condition
    if state['armed'] and hist.low[-1] <= state['entry_price']:
        state['armed'] = False
        return {"target": RISK_PERCENTAGE * state['entry_price'] / (ENTRY_ATR_MULTIPLIER * state['entry_atr']), "stop": None, "take": None}

    # 4h trend filter
    if state['armed'] and hist.htf(240).close[-1] <= get_4h_ema():
        state['armed'] = False
        return {"target": 0, "stop": None, "take": None}

    # Cooldown
    if state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Take profit and stop loss
    if state['armed']:
        take_profit = state['entry_price'] + TAKE_PROFIT_ATR_MULTIPLIER * state['entry_atr']
        stop_loss = state['entry_price'] - ENTRY_ATR_MULTIPLIER * state['entry_atr']
        if hist.high[-1] >= take_profit:
            state['armed'] = False
            return {"target": 0, "stop": None, "take": None}
        if hist.low[-1] <= stop_loss:
            state['armed'] = False
            return {"target": 0, "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}

