import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 961:
        return {"target": pos, "stop": None, "take": None}

    current_bar = len(hist) - 1
    high_96 = ind.highest(hist.high, 96)
    low_96 = ind.lowest(hist.low, 96)

    if current_bar == 960:
        state['breakout_high'] = None
        state['breakout_low'] = None
        state['stop_price'] = None
        state['take_price'] = None
        state['target_pos'] = 0

    if pos == 0:
        if hist.high[current_bar] > high_96[current_bar]:
            state['breakout_high'] = hist.high[current_bar]
            state['breakout_low'] = None
            state['stop_price'] = state['breakout_high'] - 2 * ind.atr(hist, 14)[current_bar]
            state['take_price'] = state['breakout_high'] + 1 * ind.atr(hist, 14)[current_bar]
            state['target_pos'] = 1
        elif hist.low[current_bar] < low_96[current_bar]:
            state['breakout_low'] = hist.low[current_bar]
            state['breakout_high'] = None
            state['stop_price'] = state['breakout_low'] + 2 * ind.atr(hist, 14)[current_bar]
            state['take_price'] = state['breakout_low'] - 1 * ind.atr(hist, 14)[current_bar]
            state['target_pos'] = -1

    if state['breakout_high'] is not None:
        if hist.low[current_bar] <= state['breakout_high']:
            return {"target": 1, "stop": None, "take": None}
        if hist.close[current_bar] >= state['take_price']:
            state['stop_price'] = None
            state['take_price'] = None
            state['target_pos'] = 0
        elif hist.close[current_bar] >= state['breakout_high'] + 1 * ind.atr(hist, 14)[current_bar]:
            state['target_pos'] = 0.5

    if state['breakout_low'] is not None:
        if hist.high[current_bar] >= state['breakout_low']:
            return {"target": -1, "stop": None, "take": None}
        if hist.close[current_bar] <= state['take_price']:
            state['stop_price'] = None
            state['take_price'] = None
            state['target_pos'] = 0
        elif hist.close[current_bar] <= state['breakout_low'] - 1 * ind.atr(hist, 14)[current_bar]:
            state['target_pos'] = -0.5

    return {"target": state['target_pos'], "stop": state['stop_price'], "take": state['take_price']}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RSI_OVERSOLD = 20
    RSI_OVERBOUGHT = 80
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    MAX_TRADES_PER_DAY = 3
    ENTRY_SIZE = 0.05
    ADD_SIZE = 0.025
    STOP_AND_TP = 2 * ENTRY_ATR
    TIME_STOP = 64

    # State management
    if 'last_trade_time' not in state:
        state['last_trade_time'] = 0
    if 'current_trade' not in state:
        state['current_trade'] = None
    if 'current_position' not in state:
        state['current_position'] = 0.0
    if 'current_stop' not in state:
        state['current_stop'] = None
    if 'current_tp' not in state:
        state['current_tp'] = None

    # RSI conditions
    rsi = ind.rsi(hist.close, 14)[-1]
    if rsi <= RSI_OVERSOLD and pos == 0:
        if state['last_trade_time'] == 0 or hist.time[-1] - state['last_trade_time'] > 60 * 60 * 24 * 1000:
            if state['current_trade'] is None or state['current_trade'] == 'short':
                state['current_trade'] = 'long'
                state['current_position'] = ENTRY_SIZE
                state['current_stop'] = hist.close[-1] - STOP_AND_TP
                state['current_tp'] = hist.close[-1] + STOP_AND_TP
                state['last_trade_time'] = hist.time[-1]
                return {"target": ENTRY_SIZE, "stop": state['current_stop'], "take": state['current_tp']}
    elif rsi >= RSI_OVERBOUGHT and pos == 0:
        if state['last_trade_time'] == 0 or hist.time[-1] - state['last_trade_time'] > 60 * 60 * 24 * 1000:
            if state['current_trade'] is None or state['current_trade'] == 'long':
                state['current_trade'] = 'short'
                state['current_position'] = -ENTRY_SIZE
                state['current_stop'] = hist.close[-1] + STOP_AND_TP
                state['current_tp'] = hist.close[-1] - STOP_AND_TP
                state['last_trade_time'] = hist.time[-1]
                return {"target": -ENTRY_SIZE, "stop": state['current_stop'], "take": state['current_tp']}

    # Trade management
    if state['current_trade'] is not None:
        if state['current_trade'] == 'long':
            if hist.low[-1] <= state['current_stop']:
                state['current_trade'] = None
                state['current_position'] = 0.0
                state['current_stop'] = None
                state['current_tp'] = None
                return {"target": 0.0}
            elif hist.high[-1] >= state['current_tp']:
                state['current_position'] += ADD_SIZE
                state['current_stop'] = hist.close[-1] - STOP_AND_TP
                state['current_tp'] = hist.close[-1] + STOP_AND_TP
                return {"target": state['current_position'], "stop": state['current_stop'], "take": state['current_tp']}
        elif state['current_trade'] == 'short':
            if hist.high[-1] >= state['current_stop']:
                state['current_trade'] = None
                state['current_position'] = 0.0
                state['current_stop'] = None
                state['current_tp'] = None
                return {"target": 0.0}
            elif hist.low[-1] <= state['current_tp']:
                state['current_position'] -= ADD_SIZE
                state['current_stop'] = hist.close[-1] + STOP_AND_TP
                state['current_tp'] = hist.close[-1] - STOP_AND_TP
                return {"target": state['current_position'], "stop": state['current_stop'], "take": state['current_tp']}

    # Time stop
    if state['current_trade'] is not None and hist.time[-1] - state['last_trade_time'] > 60 * 60 * 24 * 1000 * TIME_STOP:
        state['current_trade'] = None
        state['current_position'] = 0.0
        state['current_stop'] = None
        state['current_tp'] = None
        return {"target": 0.0}

    return {"target": pos, "stop": None, "take": None}

