    rsi = ind.rsi(hist.close, 21)
    current_rsi = rsi[-1]
    previous_rsi = rsi[-2]

    if pos == 0:
        if current_rsi > 25 and previous_rsi <= 25:
            atr = ind.atr(hist, 14)[-1]
            target_pos = max(0.05, min(1.0, 0.005 * hist.close[-1] / atr))
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = atr
            return {"target": target_pos, "stop": None, "take": None}
