    MAX_TRADES_PER_DAY = 3
    MAX_HOLD_BARS = 64
    EMA_PERIOD = 50
    HIGHER_TIMEFRAME = 60

    # Helper functions
    def is_trend_up(hist):
        htf_close = hist.htf(HIGHER_TIMEFRAME).close
        return htf_close[-1] > ind.ema(htf_close, EMA_PERIOD)[-1]

    def calculate_position(hist, atr):
        return 1 * hist.close[-1] / (ENTRY_ATR_MULTIPLIER * atr[-1])

    def is_profitable(hist, atr, entry_price):
        return hist.close[-1] >= entry_price + PROFIT_ATR_MULTIPLIER * atr[-1]

    def is_bearish_breakout(hist, atr, entry_price):
        return hist.low[-1] <= entry_price - PROFIT_ATR_MULTIPLIER * atr[-1]

    # Get necessary data
    atr = ind.atr(hist, ATR_PERIOD)
    entry_price = hist.close[-LOOKBACK]
    current_price = hist.close[-1]

    # Check if we are flat
    if pos == 0:
        # Check trend filter
        if is_trend_up(hist):
            # Check if we can open a new trade
            if state.get('trades_today', 0) < MAX_TRADES_PER_DAY:
                # Calculate position size
                position_size = calculate_position(hist, atr)
                # Set target and stop
                target = position_size
                stop = entry_price - PROFIT_ATR_MULTIPLIER * atr[-1]
                state['trades_today'] = state.get('trades_today', 0) + 1
                return {"target": target, "stop": stop, "take": None}
    else:
        # Check for profit or loss
        if is_profitable(hist, atr, entry_price):
            # Move stop to breakeven
            stop = entry_price
        elif is_bearish_breakout(hist, atr, entry_price):
            # Close the position
            return {"target": 0, "stop": None, "take": None}
        elif len(hist) - state.get('entry_bar', 0) >= MAX_HOLD_BARS:
            # Close the position after 64 bars
            return {"target": 0, "stop": None, "take": None}

