import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_SMA_FAST = 20
    ENTRY_SMA_SLOW = 200
    ENTRY_ATR_PERIOD = 14
    ENTRY_ATR_MULTIPLIER = 2
    ENTRY_MAX_ADDS = 1
    ENTRY_ADD_ATR_MULTIPLIER = 2
    ENTRY_ADD_SIZE_MULTIPLIER = 2
    EXIT_STOP_ATR_MULTIPLIER = 2
    EXIT_TP_ATR_MULTIPLIER = 4
    MAX_POSITION = 1.0
    MIN_POSITION = -1.0
    POSITION_GRID = 0.05

    # Helper functions
    def round_to_grid(value):
        return round(value / POSITION_GRID) * POSITION_GRID

    def get_entry_price():
        return hist.close[-1]

    def get_entry_atr():
        return ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    def get_1h_close():
        return hist.htf(60).close[-1]

    def get_1h_ema():
        return ind.ema(hist.htf(60).close, ENTRY_SMA_SLOW)[-1]

    # Check if we are already in a trade
    if pos != 0:
        return {"target": pos, "stop": None, "take": None}

    # Check if it's a new day
    if 'last_trade_date' not in state or state['last_trade_date'] != hist.time[-1] // (24 * 60 * 60 * 1000):
        state['last_trade_date'] = hist.time[-1] // (24 * 60 * 60 * 1000)
        state['entry_price'] = None
        state['entry_atr'] = None
        state['adds'] = 0

    # Check if we can enter a new trade
    if state['entry_price'] is not None:
        return {"target": pos, "stop": None, "take": None}

    # Check 1h HTF trend filter
    if get_1h_close() <= get_1h_ema():
        return {"target": pos, "stop": None, "take": None}

    # Check for golden cross
    fast_sma = ind.sma(hist.close, ENTRY_SMA_FAST)[-1]
    slow_sma = ind.sma(hist.close, ENTRY_SMA_SLOW)[-1]
    if fast_sma > slow_sma and fast_sma < slow_sma[-1]:
        state['entry_price'] = get_entry_price()
        state['entry_atr'] = get_entry_atr()
        state['adds'] = 0
        entry_size = 0.5 * state['entry_price'] / (ENTRY_ATR_MULTIPLIER * state['entry_atr'])
        entry_size = round_to_grid(entry_size)
        return {"target": entry_size, "stop": state['entry_price'] - EXIT_STOP_ATR_MULTIPLIER * state['entry_atr'], "take": state['entry_price'] + EXIT_TP_ATR_MULTIPLIER * state['entry_atr']}

    # Check for breakout
    if hist.close[-1] > ind.highest(hist.close, 20)[-1]:
        if state['entry_price'] is not None:
            if hist.close[-1] >= state['entry_price'] + ENTRY_ADD_ATR_MULTIPLIER * state['entry_atr']:
                state['adds'] += 1
                if state['adds'] <= ENTRY_MAX_ADDS:
                    add_size = entry_size * ENTRY_ADD_SIZE_MULTIPLIER
                    add_size = round_to_grid(add_size)
                    return {"target": pos + add_size, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

