import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 960:
        return {"target": pos, "stop": None, "take": None}

    ema5 = ind.ema(hist.close, 5)
    ema200 = ind.ema(hist.close, 200)

    if pos == 0:
        if ema5[-1] > ema200[-1] and ema5[-2] <= ema200[-2]:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            target = 0.75 * entry_price / (1 * entry_atr)
            stop = entry_price - 3 * entry_atr
            state['target'] = target
            state['stop'] = stop
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['in_trade'] = True
            return {"target": target, "stop": stop, "take": None}
        elif ema5[-1] < ema200[-1] and ema5[-2] >= ema200[-2]:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            target = -0.75 * entry_price / (1 * entry_atr)
            stop = entry_price + 3 * entry_atr
            state['target'] = target
            state['stop'] = stop
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['in_trade'] = True
            return {"target": target, "stop": stop, "take": None}
    else:
        if state['in_trade']:
            if hist.close[-1] >= state['entry_price'] + 2 * state['entry_atr']:
                target = pos / 2
                return {"target": target, "stop": None, "take": None}
            elif hist.close[-1] <= state['entry_price'] - 2 * state['entry_atr']:
                return {"target": 0, "stop": None, "take": None}
            else:
                return {"target": pos, "stop": state['stop'], "take": None}

    return {"target": pos, "stop": None, "take": None}

