def strategy(hist, state, pos, ind) -> dict:
    # Constants
    LOOKBACK = 96
    COOLDOWN = 4
    RISK_PER_ATR = 0.0025
    ATR_CAP = 1.0
    ATR_FLOOR = 0.05
    STOP_ATR = 1.0
    TAKE_ATR = 3.0

    # Trend filter
    ema_50 = ind.ema(hist.close, 50)
    if len(hist) < LOOKBACK + 1 or hist.close[-LOOKBACK-1] <= ema_50[-LOOKBACK-1]:
        return {"target": 0, "stop": None, "take": None}

    # Donchian breakout
    high_96 = ind.highest(hist.high, LOOKBACK)
    low_96 = ind.lowest(hist.low, LOOKBACK)
    if hist.close[-1] > high_96[-1]:
        if pos == 0:
            entry_price = hist.close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            target = min(max(RISK_PER_ATR * entry_price / entry_atr, ATR_FLOOR), ATR_CAP)
            stop = entry_price - STOP_ATR * entry_atr
            take = entry_price + TAKE_ATR * entry_atr
            state['cooldown'] = 0
            return {"target": target, "stop": stop, "take": take}
        elif state.get('cooldown', 0) == 0:
            state['cooldown'] = COOLDOWN
            return {"target": 0, "stop": None, "take": None}
    elif hist.close[-1] < low_96[-1]:
        if pos == 0:
            return {"target": 0, "stop": None, "take": None}
        elif state.get('cooldown', 0) == 0:
            state['cooldown'] = COOLDOWN
            return {"target": 0, "stop": None, "take": None}

    # Cooldown
    if state.get('cooldown', 0) > 0:
        state['cooldown'] -= 1
        return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

