def strategy(hist, state, pos, ind) -> dict:
    # Constants
    EQUITY = 1.0  # Assume 100% equity for simplicity
    RISK_PERCENT = 0.05  # 5% risk per trade
    K_ATR = 2  # Risk per K ATR
    ENTRY_ATR_PERIOD = 14
    COOLDOWN_PERIOD = 96
    PROFIT_ATR_1 = 2
    PROFIT_ATR_2 = 3
    SCALE_OUT_FRACTION = 0.5

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Initialize state variables
    if 'last_entry_price' not in state:
        state['last_entry_price'] = None
    if 'last_entry_atr' not in state:
        state['last_entry_atr'] = None
    if 'cooldown_timer' not in state:
        state['cooldown_timer'] = 0

    # Check for cooldown timer
    if state['cooldown_timer'] > 0:
        state['cooldown_timer'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for entry condition
    if pos == 0 and state['last_entry_price'] is None:
        ema_20 = ind.ema(hist.close, 20)[-1]
        ema_200 = ind.ema(hist.close, 200)[-1]
        if ema_20 > ema_200:
            state['last_entry_price'] = current_bar.close
            state['last_entry_atr'] = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
            state['cooldown_timer'] = COOLDOWN_PERIOD
            return {"target": RISK_PERCENT * state['last_entry_price'] / (K_ATR * state['last_entry_atr']), "stop": None, "take": None}

    # Check for profit conditions
    if pos > 0 and state['last_entry_price'] is not None:
        current_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]
        profit_1 = state['last_entry_price'] + PROFIT_ATR_1 * current_atr
        profit_2 = state['last_entry_price'] + PROFIT_ATR_2 * current_atr

        if current_bar.close >= profit_1:
            return {"target": 0, "stop": None, "take": None}
        if current_bar.close >= profit_2:
            return {"target": pos * (1 - SCALE_OUT_FRACTION), "stop": None, "take": None}

    # Return current position if no changes
    return {"target": pos, "stop": None, "take": None}

