def strategy(hist, state, pos, ind) -> dict:
    # Constants
    RSI_OVERSOLD = 25
    RSI_OVERBOUGHT = 75
    ENTRY_ATR_MULTIPLIER = 1.5
    POSITION_SIZE = 0.75
    COOLDOWN_PERIOD = 48
    SCALING_FACTOR = 0.5
    STOP_RATCHET = 0.0

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Get RSI and ATR values
    rsi = ind.rsi(hist.close, 14)[-1]
    atr = ind.atr(hist, 14)[-1]

    # Check for cooldown
    if 'cooldown' in state and state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for long entry
    if pos == 0 and rsi <= RSI_OVERSOLD:
        state['cooldown'] = COOLDOWN_PERIOD
        return {"target": POSITION_SIZE, "stop": None, "take": None}

    # Check for long exit
    if pos > 0 and rsi >= RSI_OVERBOUGHT:
        return {"target": 0, "stop": None, "take": None}

    # Check for scaling out
    if pos > 0 and current_bar.close >= previous_bar.close + ENTRY_ATR_MULTIPLIER * atr:
        return {"target": pos * SCALING_FACTOR, "stop": None, "take": None}

    # Ratchet stop to breakeven
    if pos > 0 and current_bar.low <= previous_bar.low:
        return {"target": pos, "stop": current_bar.low, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}

