import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    BOX_PERIOD = 64
    MAX_ATR_HEIGHT = 6
    STOP_DISTANCE = 2
    TAKE_DISTANCE = 2
    TRAIL_DISTANCE = 1.5
    EMA_PERIOD = 20
    MAX_TRADES_PER_DAY = 1

    # Helper functions
    def get_box_highs(hist, period):
        highs = hist.high
        box_highs = np.zeros(len(hist))
        for i in range(period, len(hist)):
            box_highs[i] = np.max(highs[i - period:i + 1])
        return box_highs

    def get_box_lows(hist, period):
        lows = hist.low
        box_lows = np.zeros(len(hist))
        for i in range(period, len(hist)):
            box_lows[i] = np.min(lows[i - period:i + 1])
        return box_lows

    def get_trend_filter(hist, period):
        ema = ind.ema(hist.close, period)
        return ema

    # Get indicators
    atr = ind.atr(hist, ATR_PERIOD)
    box_highs = get_box_highs(hist, BOX_PERIOD)
    box_lows = get_box_lows(hist, BOX_PERIOD)
    trend_filter = get_trend_filter(hist, EMA_PERIOD)

    # State management
    if 'last_trade_time' not in state:
        state['last_trade_time'] = 0
    if 'current_box_high' not in state:
        state['current_box_high'] = 0
    if 'current_box_low' not in state:
        state['current_box_low'] = 0
    if 'current_stop' not in state:
        state['current_stop'] = 0
    if 'current_take' not in state:
        state['current_take'] = 0

    # Determine if we can trade today
    current_time = hist.time[-1]
    if current_time // (24 * 60 * 60 * 1000) != state['last_trade_time'] // (24 * 60 * 60 * 1000):
        if abs(pos) > 0:
            return {"target": 0, "stop": None, "take": None}
        state['last_trade_time'] = current_time

    # Determine if we are in a trade
    if abs(pos) > 0:
        # Check for stop and take
        if hist.low[-1] <= state['current_stop']:
            return {"target": 0, "stop": None, "take": None}
        if hist.high[-1] >= state['current_take']:
            return {"target": 0, "stop": None, "take": None}

        # Trail the stop
        if pos > 0:
            state['current_stop'] = max(state['current_stop'], hist.low[-1] - TRAIL_DISTANCE * atr[-1])
        else:
            state['current_stop'] = min(state['current_stop'], hist.high[-1] + TRAIL_DISTANCE * atr[-1])

        return {"target": pos, "stop": state['current_stop'], "take": state['current_take']}

    # Determine if we can enter a trade
    if pos == 0 and trend_filter[-1] > hist.close[-1]:
        # Check for breakout
        if hist.close[-1] > state['current_box_high']:
            state['current_box_high'] = hist.close[-1]
            state['current_box_low'] = hist.close[-1] - MAX_ATR_HEIGHT * atr[-1]
            state['current_stop'] = hist.close[-1] - STOP_DISTANCE * atr[-1]
            state['current_take'] = hist.close[-1] + TAKE_DISTANCE * atr[-1]
            return {"target": 1, "stop": state['current_stop'], "take": state['current_take']}
    elif pos == 0 and trend_filter[-1] < hist.close[-1]:
        # Check for breakout
        if hist.close[-1] < state['current_box_low']:
            state['current_box_high'] = hist.close[-1] + MAX_ATR_HEIGHT * atr[-1]
            state['current_box_low'] = hist.close[-1]
            state['current_stop'] = hist.close[-1] + STOP_DISTANCE * atr[-1]
            state['current_take'] = hist.close[-1] - TAKE_DISTANCE * atr[-1]
            return {"target": -1, "stop": state['current_stop'], "take": state['current_take']}

    return {"target": pos, "stop": None, "take": None}

