def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    ENTRY_ATR_PERIOD = 96
    ARM_PERIOD = 64
    RISK_PERCENT = 0.0025
    MAX_POSITION = 1.0
    MIN_POSITION = 0.05
    DAILY_ENTRY_CAP = 2
    PROFIT_ATR = 1
    TAKE_PROFIT_ATR = 3

    # Get current bar index
    t = len(hist) - 1

    # Calculate ATR and entry ATR
    atr = ind.atr(hist, ATR_PERIOD)[-1]
    entry_atr = ind.atr(hist, ENTRY_ATR_PERIOD)[-1]

    # Calculate daily entry count
    if 'daily_entries' not in state:
        state['daily_entries'] = 0
    if 'last_entry_day' not in state:
        state['last_entry_day'] = hist.time[t] // (24 * 60 * 60 * 1000)

    # Check daily entry cap
    current_day = hist.time[t] // (24 * 60 * 60 * 1000)
    if current_day != state['last_entry_day']:
        state['daily_entries'] = 0
        state['last_entry_day'] = current_day

    # Check if daily entry cap is reached
    if state['daily_entries'] >= DAILY_ENTRY_CAP:
        return {"target": pos, "stop": None, "take": None}

    # Check for breakout
    if t >= ENTRY_ATR_PERIOD + ARM_PERIOD:
        high_96 = ind.highest(hist.high, ENTRY_ATR_PERIOD)[-1]
        if hist.close[t] > high_96:
            state['armed'] = True
            state['armed_high'] = high_96
        elif state['armed'] and hist.low[t] <= state['armed_high']:
            state['armed'] = False
            state['armed_high'] = None

    # Check for entry
    if state['armed'] and t >= ENTRY_ATR_PERIOD + ARM_PERIOD:
        if hist.close[t] > state['armed_high']:
            state['armed'] = False
            state['armed_high'] = None
            state['entry_price'] = hist.close[t]
            state['entry_atr'] = entry_atr
            state['position'] = min(MAX_POSITION, max(MIN_POSITION, RISK_PERCENT * hist.close[t] / (1 * entry_atr)))
            state['daily_entries'] += 1
            return {"target": state['position'], "stop": None, "take": None}

    # Check for exit conditions
    if pos != 0:
        if hist.close[t] >= state['entry_price'] + state['entry_atr'] * PROFIT_ATR:
            return {"target": 0, "stop": None, "take": None}
        elif hist.close[t] >= state['entry_price'] + state['entry_atr'] * TAKE_PROFIT_ATR:
            return {"target": pos / 2, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

