    RISK_PER_ATR = 0.0025
    POSITION_CAP = 1.0
    POSITION_FLOOR = 0.05
    MAX_ENTRIES_PER_DAY = 3
    TRAILING_STOP_ATR = 1.5

    # Get current bar and previous bar data
    current_bar = hist[-1]
    previous_bar = hist[-2]

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)[-1]

    # Calculate box high and low
    box_high = ind.highest(hist.close, BOX_PERIOD)[-1]
    box_low = ind.lowest(hist.close, BOX_PERIOD)[-1]

    # Calculate box height
    box_height = box_high - box_low

    # Check if the box height is within the allowed limit
    if box_height > MAX_ATR * atr:
        return {"target": pos, "stop": None, "take": None}

    # Check if it's a new day and we have reached the maximum number of entries
    if 'last_entry_time' in state and state['last_entry_time'] // (24 * 60 * 60 * 1000) == current_bar.time // (24 * 60 * 60 * 1000):
        if state['entry_count'] >= MAX_ENTRIES_PER_DAY:
            return {"target": pos, "stop": None, "take": None}

