    if pos == 0 and current_bar.close > box_high:
        # Calculate position size
        position_size = RISK_PER_ATR * current_bar.close / (3 * atr)
        position_size = max(POSITION_FLOOR, min(POSITION_CAP, position_size))
        state['entry_count'] = state.get('entry_count', 0) + 1
        state['last_entry_time'] = current_bar.time
        return {"target": position_size, "stop": None, "take": None}

    # Check for bearish signal
    if pos > 0 and current_bar.close < box_low:
        return {"target": 0, "stop": None, "take": None}

    # Check for profit condition
    if pos > 0 and current_bar.close >= box_high + atr:
        return {"target": 0, "stop": None, "take": None}

    # Update trailing stop
    if pos > 0:
        if 'extreme_high' not in state or current_bar.high > state['extreme_high']:
            state['extreme_high'] = current_bar.high
        trailing_stop = state['extreme_high'] - TRAILING_STOP_ATR * atr
        return {"target": pos, "stop": trailing_stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

