    def get_htf_close():
        return hist.htf(HTF_PERIOD).close

    def get_htf_ema():
        return ind.ema(hist.htf(HTF_PERIOD).close, HTF_EMA_PERIOD)

    def get_entry_price():
        return hist.close[-1]

    def get_entry_atr():
        return ind.atr(hist, ENTRY_ATR)[-1]

    def get_current_price():
        return hist.close[-1]

    def get_high_192():
        return ind.highest(hist.high, 192)[-1]

    def get_current_time():
        return hist.time[-1]

    def get_last_entry_time():
        return state.get('last_entry_time', 0)

    def get_position_fraction():
        return pos / ENTRY_SIZE

    def get_stop_price():
        return get_entry_price() - STOP_DISTANCE * get_entry_atr()

    def get_take_price():
        return get_entry_price() + TAKE_DISTANCE * get_entry_atr()

    def get_trailing_stop_price():
        return max(get_entry_price() - TRAILING_STOP_DISTANCE * get_entry_atr(), get_current_price() - TRAILING_STOP_DISTANCE * get_entry_atr())

    def should_pyramid():
        return get_current_price() >= get_entry_price() + PYRAMID_ATR * get_entry_atr()

    def should_close():
