    if pos == 0:
        if rsi[-1] < LONG_ENTRY_LEVEL and rsi[-1] > signal_line[-1] and last_4h_close > last_4h_ema:
            state['last_trade_time'] = current_bar.time
            return {"target": POSITION_SIZE, "stop": None, "take": None}
        elif rsi[-1] > SHORT_ENTRY_LEVEL and rsi[-1] < signal_line[-1] and last_4h_close < last_4h_ema:
            state['last_trade_time'] = current_bar.time
            return {"target": -POSITION_SIZE, "stop": None, "take": None}

    # Determine trailing stop
    if abs(pos) > 0:
        if pos > 0:
            extreme_price = max(hist.high[-1], hist.high[-2])
        else:
            extreme_price = min(hist.low[-1], hist.low[-2])
        trailing_stop = extreme_price - TRAILING_STOP_ATR * ind.atr(hist, ATR_PERIOD)[-1]
        return {"target": pos, "stop": trailing_stop, "take": None}

    return {"target": pos, "stop": None, "take": None}
